_FACTORIAL_CACHE = {0: 1, 1: 1}


def calculate_factorial(n):
    """Return the factorial of the non-negative integer n."""
    if n is None:
        raise ValueError("n must be provided")
    if isinstance(n, bool) or not isinstance(n, int):
        raise TypeError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non-negative")

    cached = _FACTORIAL_CACHE.get(n)
    if cached is not None:
        return cached

    highest = max(_FACTORIAL_CACHE)
    result = _FACTORIAL_CACHE[highest]
    for k in range(highest + 1, n + 1):
        result *= k
        _FACTORIAL_CACHE[k] = result
    return result


def parse_non_negative_int(text):
    """Convert text to a non-negative int, or None if it is not one."""
    stripped = text.strip()
    if not stripped:
        return None
    try:
        value = int(stripped)
    except ValueError:
        return None
    if value < 0:
        return None
    return value


def format_factorial(n, digit_limit=None):
    """Describe n! as a string, abbreviating results longer than digit_limit."""
    digits = str(calculate_factorial(n))
    if digit_limit is not None and len(digits) > digit_limit:
        digits = digits[:digit_limit] + "... (%d digits)" % len(digits)
    return "%d! = %s" % (n, digits)


def report(tokens, digit_limit=25):
    """Build a report line for every token, flagging invalid entries."""
    lines = []
    largest = None
    for token in tokens:
        n = parse_non_negative_int(token)
        if n is None:
            lines.append("%r is not a non-negative integer" % token)
            continue
        lines.append(format_factorial(n, digit_limit))
        if largest is None or n > largest:
            largest = n
    if largest is not None:
        lines.append("largest input processed: %d" % largest)
    return lines


def main(argv=None):
    if argv is None:
        import sys
        argv = sys.argv[1:]
    tokens = argv if argv else ["0", "1", "5", "10", "30", "-3", "abc"]
    for line in report(tokens):
        print(line)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

