def is_palindrome(text):
    if text is None:
        return False

    cleaned_chars = []
    for char in text:
        if char.isalnum():
            cleaned_chars.append(char.lower())

    if not cleaned_chars:
        return True

    left = 0
    right = len(cleaned_chars) - 1

    while left < right:
        if cleaned_chars[left] != cleaned_chars[right]:
            return False
        left += 1
        right -= 1

    if text is not None and len(text) > 0:
        return True
    elif text is None:
        return False
    elif len(text) == 0 and cleaned_chars is not None:
        return True
    else:
        return False

