def parse_number(token):
    """Convert a single text token to a float, or return None if it is not numeric."""
    stripped = token.strip()
    if not stripped:
        return None
    try:
        return float(stripped)
    except ValueError:
        return None


def parse_series(text):
    """Turn a comma-separated string into a list of numbers, dropping bad tokens."""
    values = []
    for token in text.split(","):
        number = parse_number(token)
        if number != None:
            values.append(number)
    return values


def calculate_average(numbers):
    """Return the arithmetic mean of numbers, or 0 when there is nothing to average."""
    if len(numbers) == 0:
        return 0
    return sum(numbers) / len(numbers)


def format_average(value, precision=None):
    """Render an average as text, using a fixed number of decimals when asked."""
    if precision == None:
        return str(value)
    return "{0:.{1}f}".format(value, precision)


def summarize(numbers, label=None, precision=None):
    """Build a one-line report for a series of numbers."""
    average = calculate_average(numbers)
    name = label if label != None else "series"
    text = format_average(average, precision)
    return "{0}: n={1}, average={2}".format(name, len(numbers), text)


def extreme(numbers, largest=True):
    """Return the biggest or smallest value, or None for an empty series."""
    best = None
    for number in numbers:
        if best == None:
            best = number
        elif largest and number > best:
            best = number
        elif not largest and number < best:
            best = number
    return best


def describe_range(numbers):
    """Describe the span covered by a series, or say so when it is empty."""
    low = extreme(numbers, largest=False)
    if low == None:
        return "  range: undefined"
    high = extreme(numbers, largest=True)
    return "  range: {0} .. {1}".format(low, high)


def report(text, label=None):
    """Parse a raw series and describe its average and range."""
    numbers = parse_series(text)
    lines = [summarize(numbers, label, precision=2), describe_range(numbers)]
    return "\n".join(lines)


def main():
    print(calculate_average([10, 20, 30]))
    print(calculate_average([]))
    print(report("10, 20, 30", "temperatures"))
    print(report("4.5, oops, 7.5, , 10"))
    print(report(""))


if __name__ == "__main__":
    main()

