import sys

SEARCH_WINDOW = 500
_CACHE = {}


def parse_int(text):
    """Return the integer contained in `text`, or None if it is not a valid integer."""
    stripped = text.strip()
    if not stripped:
        return None
    sign = 1
    if stripped[0] in "+-":
        if stripped[0] == "-":
            sign = -1
        stripped = stripped[1:]
    if not stripped.isdigit():
        return None
    return sign * int(stripped)


def read_numbers(argv, fallback=None):
    """Parse the command line into integers, falling back to a demo list."""
    if fallback is None:
        fallback = [7, 10, 1, 97, 561]
    numbers = []
    for arg in argv:
        value = parse_int(arg)
        if value is None:
            print("skipping unparsable argument: %r" % arg)
            continue
        numbers.append(value)
    return numbers or list(fallback)


def is_prime(n):
    """Determine whether the positive integer `n` is prime."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("is_prime() expects an int")
    if n < 2:
        return False
    cached = _CACHE.get(n)
    if cached is not None:
        return cached
    result = True
    if n % 2 == 0:
        result = n == 2
    else:
        divisor = 3
        while divisor * divisor <= n:
            if n % divisor == 0:
                result = False
                break
            divisor += 2
    _CACHE[n] = result
    return result


def next_prime(n, ceiling=None):
    """Smallest prime greater than `n`, or None if none is found up to `ceiling`."""
    candidate = max(n, 1) + 1
    while True:
        if ceiling is not None and candidate > ceiling:
            return None
        if is_prime(candidate):
            return candidate
        candidate += 1


def prime_factors(n):
    """Ascending list of prime factors of `n` (with multiplicity); empty for n < 2."""
    factors = []
    remaining = n
    factor = 2
    while factor * factor <= remaining:
        while remaining % factor == 0:
            factors.append(factor)
            remaining //= factor
        factor = 3 if factor == 2 else factor + 2
    if remaining > 1:
        factors.append(remaining)
    return factors


def largest_prime_factor(n, factors=None):
    """Biggest prime factor of `n`, or None when `n` has no factorisation."""
    if factors is None:
        factors = prime_factors(n)
    if not factors:
        return None
    return factors[-1]


def describe(n):
    """Human readable one-line report about `n`."""
    if n < 1:
        return "%d is not a positive integer" % n
    if is_prime(n):
        nxt = next_prime(n, n + SEARCH_WINDOW)
        if nxt is None:
            return "%d is prime; no further prime within %d" % (n, SEARCH_WINDOW)
        return "%d is prime; the next prime is %d" % (n, nxt)
    factors = prime_factors(n)
    biggest = largest_prime_factor(n, factors)
    if biggest is None:
        return "%d is neither prime nor composite" % n
    pieces = " * ".join(str(f) for f in factors)
    return "%d is not prime: %s (largest factor %d)" % (n, pieces, biggest)


def main(argv):
    for number in read_numbers(argv):
        print(describe(number))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

