import math
import sys

DEFAULT_DIGITS = 4


def parse_number(token):
    """Return the float value of a token, or None if it is not a number."""
    try:
        return float(token)
    except ValueError:
        return None


def parse_series(text):
    values = []
    for token in text.replace(",", " ").split():
        value = parse_number(token)
        if value is None:
            raise ValueError("not a number: %r" % token)
        values.append(value)
    return values


def first_nonpositive(numbers):
    """Return the first value that is not positive, or None if all are."""
    for number in numbers:
        if number <= 0:
            return number
    return None


def geometric_mean(numbers):
    """Return the Nth root of the product of the N given positive numbers."""
    if numbers is None:
        raise ValueError("numbers must be a sequence, not None")
    values = list(numbers)
    if not values:
        raise ValueError("geometric mean of an empty sequence is undefined")
    bad = first_nonpositive(values)
    if bad is not None:
        raise ValueError("all numbers must be positive, got %r" % bad)
    return math.prod(values) ** (1.0 / len(values))


def safe_geometric_mean(numbers, default=None):
    try:
        return geometric_mean(numbers)
    except ValueError:
        return default


def format_mean(label, mean, digits=None):
    if digits is None:
        digits = DEFAULT_DIGITS
    if mean is None:
        return "%s: undefined" % label
    rounded = round(mean, digits)
    if rounded == int(rounded):
        return "%s: %.1f" % (label, rounded)
    return "%s: %s" % (label, rounded)


def describe(label, text, digits=None):
    try:
        values = parse_series(text)
    except ValueError as exc:
        return "%s: input error (%s)" % (label, exc)
    return format_mean(label, safe_geometric_mean(values), digits)


def series_from_argv(argv):
    """Join the command-line arguments, or None when none were given."""
    if len(argv) > 1:
        return " ".join(argv[1:])
    return None


def main(argv):
    text = series_from_argv(argv)
    if text is not None:
        print(describe("argv", text))
        return
    for label, sample in (("pair", "2, 8"), ("ones", "1 1 1"),
                          ("growth", "1.05 1.10 0.98 1.20"), ("bad", "3 -4")):
        print(describe(label, sample))


if __name__ == "__main__":
    main(sys.argv)

