import math
import sys


def circle_area(radius):
    """Return the area of a circle with the given radius."""
    if radius is None:
        raise TypeError("radius must be a number, not None")
    if radius < 0:
        raise ValueError("radius must be non-negative")
    return math.pi * float(radius) ** 2


def parse_radius(text):
    """Convert a text field into a radius, or None if it is not usable."""
    if text is None:
        return None
    cleaned = text.strip()
    if not cleaned:
        return None
    try:
        value = float(cleaned)
    except ValueError:
        return None
    if value < 0:
        return None
    return value


def format_area(area, digits=None):
    """Render an area, rounded to `digits` places when a precision is given."""
    if digits is None:
        return repr(area)
    return "{0:.{1}f}".format(area, digits)


def describe(text, digits=None):
    """Build a one-line report for a single radius field."""
    radius = parse_radius(text)
    if radius is None:
        return "radius {0!r}: invalid input".format(text)
    area = circle_area(radius)
    return "radius {0:g}: area = {1}".format(radius, format_area(area, digits))


def total_area(values):
    """Sum the areas of every valid radius, skipping the unusable ones."""
    total = 0.0
    for text in values:
        radius = parse_radius(text)
        if radius is not None:
            total += circle_area(radius)
    return total


def main(argv=None):
    if argv is None:
        argv = sys.argv[1:]
    digits = None
    fields = []
    for arg in argv:
        if arg.startswith("--digits="):
            digits = int(arg.split("=", 1)[1])
        else:
            fields.append(arg)
    if not fields:
        fields = ["1", "0", "2.5", "abc", "-3"]
    for field in fields:
        print(describe(field, digits))
    print("combined area = " + format_area(total_area(fields), digits))
    return 0


if __name__ == "__main__":
    sys.exit(main())

