DAYS_IN_MONTH = (31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31)


def is_leap_year(year):
    return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)


def days_in_month(year, month):
    if month < 1 or month > 12:
        return None
    if month == 2 and is_leap_year(year):
        return 29
    return DAYS_IN_MONTH[month - 1]


def validate_date(year, month, day):
    limit = days_in_month(year, month)
    if limit is None:
        return f"month {month} is out of range"
    if day < 1 or day > limit:
        return f"day {day} is out of range for month {month} of {year}"
    return None


def format_date(year, month, day):
    problem = validate_date(year, month, day)
    if problem is not None:
        raise ValueError(problem)
    return f"{year:04d}-{month:02d}-{day:02d}"


def parse_date(text):
    parts = text.strip().split("-")
    if len(parts) != 3:
        return None
    try:
        year, month, day = (int(part) for part in parts)
    except ValueError:
        return None
    if validate_date(year, month, day) is not None:
        return None
    return year, month, day


def normalize_date(text, fallback=None):
    parsed = parse_date(text)
    if parsed is None:
        if fallback is None:
            return None
        return format_date(*fallback)
    return format_date(*parsed)


def main():
    samples = [(2023, 7, 15), (2020, 1, 1), (999, 12, 31), (2021, 2, 29)]
    for year, month, day in samples:
        problem = validate_date(year, month, day)
        if problem is None:
            print(f"{year}/{month}/{day} -> {format_date(year, month, day)}")
        else:
