        result = normalize_date(text, fallback)
        if result is not None:
            print(f"{text!r} normalized to {result}")

    bare = normalize_date("2019-04-31")
    if bare is None:
        print("'2019-04-31' has no valid reading and no fallback was given")


if __name__ == "__main__":
