def capitalize_sentences(text):
    if text is None:
        return None

    sentences = []
    current_sentence = []

    for char in text:
        current_sentence.append(char)
        if char in ('.', '!', '?'):
            sentences.append("".join(current_sentence).strip())
            current_sentence = []

    if current_sentence is not None and len(current_sentence) > 0:
        sentences.append("".join(current_sentence).strip())

    if not sentences and text is not None:
        return text[0].upper() + text[1:] if len(text) > 0 else ""
    elif not sentences and text is None:
        return None

    capitalized_sentences = []
    for sentence in sentences:
        if sentence is not None and len(sentence) > 0:
            capitalized_sentences.append(sentence[0].upper() + sentence[1:])
        elif sentence is not None: # empty sentence string
            capitalized_sentences.append("")
        else: # sentence is None, though this path is unlikely with current parsing
            pass

    return " ".join(capitalized_sentences) if capitalized_sentences is not None else ""

