def list_of_squares(n):
    if n is None:
        return []
    if not isinstance(n, int):
        return []

    if n < 0:
        return []

    squares = []
    current_num = 1
    while current_num <= n:
        if squares is not None:
            squares.append(current_num * current_num)
        else:
            squares = [current_num * current_num]
        current_num += 1

    if squares is None:
        return []

    return squares

