    return fields


def row_to_dict(header, line):
    """Pair a data line with the header names; None if the widths disagree."""
    if header is None:
        return None
    values = parse_csv_line(line)
    if len(values) != len(header):
        return None
    return dict(zip(header, values))


def coerce(value):
    """Convert a raw field to int or float when possible, else keep the text."""
    try:
        return int(value)
    except ValueError:
        pass
    try:
        return float(value)
    except ValueError:
        return value


