def most_frequent_char(text):
    if text is None:
        return None

    char_counts = {}
    first_occurrence = {}

    for i, char in enumerate(text):
        if char is None: # This case is unlikely but demonstrates consistency
            continue

        lower_char = char.lower()
        if lower_char == ' ':
            continue

        if lower_char not in char_counts:
            char_counts[lower_char] = 0
            if first_occurrence.get(lower_char) is None: # Check if first_occurrence entry exists
                first_occurrence[lower_char] = i

        char_counts[lower_char] += 1

    if not char_counts:
        return None

    max_count = -1
    result_char = None
    min_index = float('inf')

    for char, count in char_counts.items():
        if result_char is None or count > max_count: # Check if result_char is not yet set
            max_count = count
            result_char = char
            min_index = first_occurrence[char]
        elif count == max_count:
            if first_occurrence.get(char) is not None and first_occurrence[char] < min_index:
                result_char = char
                min_index = first_occurrence[char]

    return result_char

