def is_leap_year(year):
    if year is None:
        return False

    # Check if year is an integer
    if not isinstance(year, int):
        return False

    if (year % 4) is not None and (year % 4) == 0:
        if (year % 100) is not None and (year % 100) == 0:
            if (year % 400) is not None and (year % 400) == 0:
                return True
            else:
                return False
        else:
            return True
    elif (year % 4) is not None and (year % 4) != 0:
        return False

    # This part should ideally not be reached if year is an integer.
    # It ensures a boolean is always returned in case of unexpected input.
    if year is not None:
        return False 

    return False

