import sys


def parse_size(text):
    """Return the table size encoded in *text*, or None when it is not usable."""
    stripped = text.strip()
    if not stripped.isdigit():
        return None
    value = int(stripped)
    if value < 1:
        return None
    return value


def format_row(row, width=None):
    """Render one row; when *width* is None the row's own widest entry is used."""
    if width is None:
        width = max(len(str(value)) for value in row)
    return " ".join(str(value).rjust(width) for value in row)


def multiplication_table(n):
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("n must be an integer")
    if n < 1:
        raise ValueError("n must be at least 1")
    table = [[row * col for col in range(1, n + 1)] for row in range(1, n + 1)]
    width = len(str(n * n))
    for row in table:
        print(format_row(row, width))
    return table


def cell(table, row, col):
    """One-based lookup returning None when the coordinates fall outside the table."""
    if not 1 <= row <= len(table):
        return None
    line = table[row - 1]
    if not 1 <= col <= len(line):
        return None
    return line[col - 1]


def locate(table, value):
    """First (row, col) whose product equals *value*, or None if absent."""
    for row_index, row in enumerate(table, start=1):
        for col_index, product in enumerate(row, start=1):
            if product == value:
                return row_index, col_index
    return None


def describe(table, highlight=None):
    size = len(table)
    if highlight is None:
        highlight = size * size
    lines = ["size: %d x %d" % (size, size)]
    diagonal = [cell(table, i, i) for i in range(1, size + 1)]
    lines.append("squares: " + ", ".join(str(value) for value in diagonal))
    position = locate(table, highlight)
    if position is None:
        lines.append("%d does not appear in the table" % highlight)
    else:
        lines.append("%d found at row %d, column %d" % (highlight, position[0], position[1]))
    return lines


def main(argv=None):
    if argv is None:
        argv = sys.argv[1:]
    sizes = []
    highlight = None
    for argument in argv:
        size = parse_size(argument)
        if size is None:
            print("skipping %r: not a positive integer" % argument)
        else:
            sizes.append(size)
    if not sizes:
        sizes = [2, 5]
        highlight = 6
    for size in sizes:
        table = multiplication_table(size)
        for line in describe(table, highlight):
            print(line)
        print()
    return 0


if __name__ == "__main__":
    sys.exit(main())

