def locate(table, value):
    """First (row, col) whose product equals *value*, or None if absent."""
    for row_index, row in enumerate(table, start=1):
        for col_index, product in enumerate(row, start=1):
            if product == value:
                return row_index, col_index
    return None


def describe(table, highlight=None):
    size = len(table)
    if highlight == None:
        highlight = size * size
    lines = ["size: %d x %d" % (size, size)]
    diagonal = [cell(table, i, i) for i in range(1, size + 1)]
    lines.append("squares: " + ", ".join(str(value) for value in diagonal))
    position = locate(table, highlight)
    if position == None:
        lines.append("%d does not appear in the table" % highlight)
    else:
        lines.append("%d found at row %d, column %d" % (highlight, position[0], position[1]))
    return lines


def main(argv=None):
    if argv == None:
        argv = sys.argv[1:]
    sizes = []
    highlight = None
    for argument in argv:
        size = parse_size(argument)
        if size == None:
            print("skipping %r: not a positive integer" % argument)
        else:
            sizes.append(size)
    if not sizes:
        sizes = [2, 5]
        highlight = 6
    for size in sizes:
        table = multiplication_table(size)
        for line in describe(table, highlight):
            print(line)
        print()
    return 0


if __name__ == "__main__":
    sys.exit(main())

