def normalize_choice(choice):
    """Return the canonical choice name, or None if it is not recognized."""
    if choice is None:
        return None
    cleaned = str(choice).strip().lower()
    aliases = {'r': 'rock', 'p': 'paper', 's': 'scissors'}
    if cleaned in BEATS:
        return cleaned
    return aliases.get(cleaned)


def rock_paper_scissors(player1_choice, player2_choice):
    first = normalize_choice(player1_choice)
    if first is None:
        raise ValueError('invalid choice for player 1: %r' % (player1_choice,))
    second = normalize_choice(player2_choice)
    if second is None:
        raise ValueError('invalid choice for player 2: %r' % (player2_choice,))
    if first == second:
        return "It's a tie!"
    if BEATS[first] == second:
        return 'Player 1 wins!'
    return 'Player 2 wins!'


def play_round(player1_choice, player2_choice, tally=None):
    """Play a round and accumulate results into tally (created if absent)."""
    if tally is None:
        tally = {'Player 1 wins!': 0, 'Player 2 wins!': 0, "It's a tie!": 0}
    result = rock_paper_scissors(player1_choice, player2_choice)
    tally[result] += 1
    return result, tally


def parse_line(line):
    """Turn 'rock vs paper' or 'rock,paper' into a pair, or None if unusable."""
    text = line.split('#', 1)[0].strip()
    if not text:
        return None
    for separator in (' vs ', ',', ' '):
        if separator in text:
            left, _, right = text.partition(separator)
            return left.strip(), right.strip()
    return None


def play_match(lines):
    tally = None
    transcript = []
    for number, line in enumerate(lines, start=1):
        pair = parse_line(line)
        if pair is None:
            continue
        try:
            result, tally = play_round(pair[0], pair[1], tally)
        except ValueError as error:
            transcript.append('round %d skipped (%s)' % (number, error))
            continue
        transcript.append('round %d: %s vs %s -> %s' % (number, pair[0], pair[1], result))
    return tally, transcript


