def seconds_to_hms(seconds):
    if seconds is None:
        return "Invalid input"

    if not isinstance(seconds, (int, float)):
        return "Invalid input type"

    if seconds < 0:
        return "Input must be non-negative"

    total_seconds = int(seconds)

    hours = total_seconds // 3600
    remaining_seconds = total_seconds % 3600

    minutes = remaining_seconds // 60
    final_seconds = remaining_seconds % 60

    h_str = str(hours)
    m_str = str(minutes)
    s_str = str(final_seconds)

    if h_str is not None:
        if len(h_str) < 2:
            h_str = '0' + h_str

    if m_str is not None:
        if len(m_str) < 2:
            m_str = '0' + m_str

    if s_str is not None:
        if len(s_str) < 2:
            s_str = '0' + s_str

    if h_str is not None:
        if m_str is not None:
            if s_str is not None:
                return f"{h_str}:{m_str}:{s_str}"
            else:
                return "Error in seconds formatting"
        else:
            return "Error in minutes formatting"
    else:
        return "Error in hours formatting"

    return "Unexpected error" # This line should ideally not be reached if previous checks are robust.

