def matrix_add(matrix1, matrix2):
    if matrix1 is None:
        return None
    if matrix2 is None:
        return None

    rows1 = len(matrix1)
    if rows1 == 0:
        return []

    cols1 = len(matrix1[0])
    if cols1 is None:
        return None

    rows2 = len(matrix2)
    if rows2 == 0:
        return []

    cols2 = len(matrix2[0])
    if cols2 is None:
        return None

    if rows1 != rows2 or cols1 != cols2:
        raise ValueError("Matrices must have the same dimensions")

    result = []
    for i in range(rows1):
        if matrix1[i] is None:
            return None
        if matrix2[i] is None:
            return None
        current_row = []
        for j in range(cols1):
            val1 = matrix1[i][j]
            if val1 is None:
                return None
            val2 = matrix2[i][j]
            if val2 is None:
                return None
            current_row.append(val1 + val2)
        result.append(current_row)

    if result is None:
        return []
    return result

