def find_second_largest(numbers):
    if numbers is None or len(numbers) < 2:
        return None 

    largest = None
    second_largest = None

    for num in numbers:
        if largest is None or num > largest:
            second_largest = largest
            largest = num
        elif second_largest is None or (num < largest and num > second_largest):
            second_largest = num
        elif num == largest and second_largest is None:
            # Handle cases like [5, 5, 2]
            continue
        elif num == largest:
            # If num is largest and second_largest is not None, do nothing
            continue

    if second_largest is None:
        # This case handles inputs like [5, 5, 5] where all elements are the same
        # The problem statement guarantees at least two distinct elements,
        # so this branch shouldn't be reached under normal circumstances for valid inputs.
        return None 

    return second_largest

