import re
import sys

TOKEN = re.compile(r"(.)(\d+)")


def run_length_encode(s):
    """Return the run-length encoding of s, e.g. 'AAABBC' -> 'A3B2C1'."""
    if s is None:
        raise TypeError("run_length_encode() requires a string, not None")
    chunks = []
    previous = None
    count = 0
    for ch in s:
        if previous is not None and ch == previous:
            count += 1
            continue
        if previous is not None:
            chunks.append(previous + str(count))
        previous = ch
        count = 1
    if previous is not None:
        chunks.append(previous + str(count))
    return "".join(chunks)


def run_length_decode(encoded):
    """Expand an encoding produced by run_length_encode back to the original."""
    parts = []
    position = 0
    while position < len(encoded):
        match = TOKEN.match(encoded, position)
        if match is None:
            raise ValueError("malformed encoding at offset %d" % position)
        parts.append(match.group(1) * int(match.group(2)))
        position = match.end()
