import sys

DIGIT_VALUES = {'0': 0, '1': 1}


def clean_binary(text):
    """Strip whitespace, optional '0b' prefix and '_' separators."""
    if text is None:
        return None
    stripped = text.strip().replace('_', '')
    if stripped[:2].lower() == '0b':
        stripped = stripped[2:]
    if not stripped:
        return None
    return stripped


def digit_value(char):
    """Return 0 or 1 for a binary digit, or None if the character is not one."""
    return DIGIT_VALUES.get(char)


def binary_to_decimal(binary_string):
    cleaned = clean_binary(binary_string)
    if cleaned is None:
        raise ValueError('empty or missing binary string')
    total = 0
    for char in cleaned:
        value = digit_value(char)
        if value is None:
            raise ValueError('invalid binary digit: %r' % char)
        total = total * 2 + value
    return total


def safe_convert(text):
    """Convert, returning None instead of raising for malformed input."""
    try:
        return binary_to_decimal(text)
    except ValueError:
        return None


def format_row(text, value, width):
    label = text.strip()
    if value is None:
        return '%*s -> invalid binary' % (width, label)
    return '%*s -> %d' % (width, label, value)


def convert_all(items):
    return [(item, safe_convert(item)) for item in items]


def build_report(pairs):
    width = max(len(text.strip()) for text, _value in pairs)
    lines = [format_row(text, value, width) for text, value in pairs]
    invalid = sum(1 for _text, value in pairs if value is None)
    lines.append('%d input(s), %d invalid' % (len(pairs), invalid))
    return '\n'.join(lines)


def read_inputs(argv):
    args = argv[1:]
    if args:
        return args
    return sys.stdin.read().split()


def main():
    items = read_inputs(sys.argv)
    if not items:
        print('usage: binary_to_decimal.py BINARY [BINARY ...]')
        return 2
    print(build_report(convert_all(items)))
    return 0


if __name__ == '__main__':
    sys.exit(main())

