    elif description is not None:
        if status_code == 200 and description is not None:
            return description
        elif status_code == 404 and description is not None:
            return description
        elif status_code == 500 and description is not None:
            return description
        else:
            return 'Unknown Status'
    else:
        return 'Unknown Status'

