PAIRS = {')': '(', ']': '[', '}': '{'}


def matching_open(ch):
    """Return the opening character that closes with `ch`, or None."""
    return PAIRS.get(ch)


def find_mismatch(s):
    """Return the index of the first character that breaks the balance.

    Returns None when the string is completely valid.
    """
    if s is None:
        raise TypeError("expected a string, got None")
    stack = []
    for index, ch in enumerate(s):
        opener = matching_open(ch)
        if opener is None:
            if ch not in PAIRS.values():
                raise ValueError("unexpected character %r at index %d" % (ch, index))
            stack.append((ch, index))
        else:
            top = stack.pop() if stack else None
            if top is None or top[0] != opener:
                return index
    if stack:
        return stack[0][1]
    return None


def is_valid_parentheses(s):
    """True when every bracket in `s` is matched and properly nested."""
    return find_mismatch(s) is None


def describe(s):
    """Build a one-line human readable verdict for `s`."""
    try:
        bad = find_mismatch(s)
    except (TypeError, ValueError) as exc:
        return "%r -> error: %s" % (s, exc)
    shown = repr(s) if s else "'' (empty)"
    if bad is not None:
        return "%s -> invalid, first problem at index %d (%r)" % (shown, bad, s[bad])
    return "%s -> valid" % shown


def longest_valid_prefix(s):
    """Return the longest prefix of `s` that is itself valid."""
    best = ""
    for end in range(len(s) + 1):
        prefix = s[:end]
        try:
            valid = is_valid_parentheses(prefix)
        except ValueError:
            break
        if valid:
            best = prefix
    return best


def main():
    samples = ["()[]{}", "([)]", "", "{[()]}", "(]", "((((", "()) ", None, "{[()]}((("]
    for sample in samples:
        print(describe(sample))
        if sample is not None and not is_valid_parentheses_safe(sample):
            print("    longest valid prefix: %r" % longest_valid_prefix(sample))


def is_valid_parentheses_safe(s):
    """Like `is_valid_parentheses`, but treats stray characters as invalid."""
    try:
        return is_valid_parentheses(s)
    except ValueError:
        return False


if __name__ == "__main__":
    main()

