import math


def parse_token(token):
    try:
        return float(token)
    except ValueError:
        return None


def parse_numbers(text):
    """Parse whitespace/comma separated numbers; None if the record is unusable."""
    values = []
    for token in text.replace(",", " ").split():
        value = parse_token(token)
        if value is None:
            return None
        values.append(value)
    if len(values) < 2:
        return None
    return values


def calculate_std_dev(numbers):
    """Sample standard deviation; assumes at least two numbers."""
    mean = sum(numbers) / len(numbers)
    squared_deviations = sum((value - mean) ** 2 for value in numbers)
    return math.sqrt(squared_deviations / (len(numbers) - 1))


def coefficient_of_variation(numbers):
    """Relative spread as a percentage, or None when the mean is zero."""
    mean = sum(numbers) / len(numbers)
    if mean == 0:
        return None
    return 100.0 * calculate_std_dev(numbers) / mean


def most_variable(records):
    """Label of the record with the largest spread, or None if none are usable."""
    best_label = None
    best_sd = None
    for label, numbers in records:
        if numbers is None:
            continue
        sd = calculate_std_dev(numbers)
        if best_sd is None or sd > best_sd:
            best_label, best_sd = label, sd
    return best_label


def describe(label, numbers):
    """Report line for one dataset, or an error line for rejected input."""
    if numbers is None:
        return "{0}: unusable input (need at least two numbers)".format(label)
    mean = sum(numbers) / len(numbers)
    summary = "{0}: n={1} mean={2:.3f} sd={3:.3f}".format(
        label, len(numbers), mean, calculate_std_dev(numbers))
    cv = coefficient_of_variation(numbers)
    if cv is None:
        return summary + " cv=undefined (mean is zero)"
    return summary + " cv={0:.1f}%".format(cv)


def main():
    datasets = [("sample", "1 2 3 4 5"), ("flat", "10, 10, 10"),
                ("centred", "-3 0 3"), ("broken", "4 five 6")]
    records = [(label, parse_numbers(raw)) for label, raw in datasets]
    for label, numbers in records:
        print(describe(label, numbers))
    widest = most_variable(records)
    if widest is None:
        print("no usable datasets")
    else:
        print("largest spread: {0}".format(widest))


if __name__ == "__main__":
    main()

