import random
import sys


def roll_dice(num_dice, sides):
    """Roll `num_dice` dice with `sides` faces each and return the outcomes."""
    if num_dice < 1:
        raise ValueError("num_dice must be at least 1")
    if sides < 2:
        raise ValueError("sides must be at least 2")
    return [random.randint(1, sides) for _ in range(num_dice)]


def apply_keep(rolls, keep):
    """Return the highest `keep` rolls, or every roll when `keep` is None."""
    if keep is None:
        return list(rolls)
    return sorted(rolls, reverse=True)[:keep]


def parse_notation(text):
    """Parse dice notation like '3d6', '2d10+4' or '4d6k3'; return None if invalid."""
    cleaned = text.strip().lower().replace(" ", "")
    if "d" not in cleaned:
        return None
    count_part, _, rest = cleaned.partition("d")
    modifier = None
    for symbol in ("+", "-"):
        if symbol in rest:
            rest, _, mod_part = rest.partition(symbol)
            try:
                modifier = int(symbol + mod_part)
            except ValueError:
                return None
            break
    if modifier is None:
        modifier = 0
    keep = None
    if "k" in rest:
        rest, _, keep_text = rest.partition("k")
        if not keep_text.isdigit() or keep_text == "0":
            return None
        keep = int(keep_text)
    count_text = count_part if count_part else "1"
    if not count_text.isdigit() or not rest.isdigit():
        return None
    count = int(count_text)
    if keep is not None and keep > count:
        return None
    return count, int(rest), modifier, keep


def histogram(rolls, sides):
    """Count how often each face appeared."""
    counts = {face: 0 for face in range(1, sides + 1)}
    for value in rolls:
        counts[value] += 1
    return counts


def format_report(notation, rolls, sides, modifier, keep):
    kept = apply_keep(rolls, keep)
    lines = ["%s -> %s" % (notation, ", ".join(str(r) for r in rolls))]
    if keep is not None:
        lines.append("kept: %s" % ", ".join(str(r) for r in kept))
    total = sum(kept)
    if modifier:
        lines.append("total: %d (%d %+d)" % (total + modifier, total, modifier))
    else:
        lines.append("total: %d" % total)
    for face, count in sorted(histogram(rolls, sides).items()):
        lines.append("  %2d | %s" % (face, "*" * count))
    return "\n".join(lines)


def main(argv):
    seed = None
    args = []
    for arg in argv:
        if arg.startswith("--seed="):
            seed = int(arg.split("=", 1)[1])
        else:
            args.append(arg)
    if seed is not None:
        random.seed(seed)
    if not args:
        args = ["3d6", "2d10+4", "4d6k3"]
    status = 0
    for notation in args:
        parsed = parse_notation(notation)
        if parsed is None:
            print("cannot parse %r, expected something like 3d6" % notation)
            status = 1
            continue
        num_dice, sides, modifier, keep = parsed
        rolls = roll_dice(num_dice, sides)
        print(format_report(notation, rolls, sides, modifier, keep))
    return status


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

