def has_conflict(schedule, new_event_start, new_event_end):
    if schedule is None:
        return False

    if not isinstance(schedule, list):
        return False

    if new_event_start is None:
        return True

    if new_event_end is None:
        return True

    if not schedule:
        return False

    for event_start, event_end in schedule:
        if event_start is None:
            continue
        if event_end is None:
            continue

        # Check for overlap:
        # 1. New event starts before existing event ends AND existing event starts before new event ends
        # 2. (new_event_start < event_end) and (event_start < new_event_end)

        # Simplified overlap condition:
        # If the new event's start is before the existing event's end, AND
