def parse_number(text):
    """Return the positive integer described by text, or None if it is invalid."""
    stripped = text.strip()
    if not stripped.isdigit() or int(stripped) == 0:
        return None
    return int(stripped)


def parse_args(args):
    """Split args into a listing limit, raw number strings and rejected inputs."""
    limit = None
    numbers = []
    errors = []
    for raw in args:
        if not raw.startswith("--limit="):
            numbers.append(raw)
            continue
        parsed = parse_number(raw[len("--limit="):])
        if parsed is None:
            errors.append(raw)
        else:
            limit = parsed
    return limit, numbers, errors


def normalize(number):
    """Return number as a positive int, raising ValueError when it is not one."""
    value = parse_number(number) if isinstance(number, str) else number
    if value is None or isinstance(value, bool) or not isinstance(value, int) or value <= 0:
        raise ValueError("expected a positive integer, got {!r}".format(number))
    return value


def is_armstrong(number):
    """Return True if number equals the sum of its digits raised to digit count."""
    value = normalize(number)
    digits = str(value)
    power = len(digits)
    total = sum(int(digit) ** power for digit in digits)
    is_armstrong_number = total == value
    return is_armstrong_number


def armstrong_numbers_between(start, end=None):
    """List Armstrong numbers in [start, end]; a lone argument means 1..start."""
    if end is None:
        start, end = 1, start
    return [n for n in range(max(1, start), end + 1) if is_armstrong(n)]


def describe(number):
    """Return a human readable explanation of the Armstrong check."""
    value = normalize(number)
    digits = str(value)
    power = len(digits)
    terms = " + ".join("{}^{}".format(d, power) for d in digits)
    total = sum(int(d) ** power for d in digits)
    verdict = "is" if total == value else "is not"
    return "{} = {} -> {} {} an Armstrong number".format(terms, total, value, verdict)


def main(argv=None):
    import sys
    args = argv
    if args is None:
        args = sys.argv[1:]
    limit, numbers, errors = parse_args(args)
    status = 0
    for raw in errors:
        print("bad limit option: {!r}".format(raw))
        status = 1
    if limit is None and not numbers:
        limit = 1000
    if limit is not None:
        found = armstrong_numbers_between(limit)
        print("Armstrong numbers up to {}: ".format(limit) + ", ".join(str(n) for n in found))
    for raw in numbers:
        try:
            print(describe(raw))
        except ValueError as exc:
            print("skipping input: {}".format(exc))
            status = 1
    return status


if __name__ == "__main__":
    raise SystemExit(main())

