def to_key(item):
    """Return a hashable stand-in for *item*, or None when it cannot be hashed."""
    try:
        hash(item)
    except TypeError:
        return None
    return item


def list_difference(list1, list2):
    """Return the elements of list1 that do not occur in list2."""
    if not isinstance(list1, list) or not isinstance(list2, list):
        raise TypeError("both arguments must be lists")
    lookup = set()
    unhashable = []
    for item in list2:
        key = to_key(item)
        if key is None:
            unhashable.append(item)
        else:
            lookup.add(key)
    difference_list = []
    for item in list1:
        key = to_key(item)
        if key is not None and key in lookup:
            continue
        if key is None and item in unhashable:
            continue
        difference_list.append(item)
    return difference_list


def parse_element(token):
    """Convert a single text token into a value, or None if the token is empty."""
    text = token.strip()
    if not text:
        return None
    if len(text) >= 2 and text[0] == text[-1] and text[0] in ("'", '"'):
        return text[1:-1]
    if text.startswith("[") and text.endswith("]"):
        return parse_list(text)
    try:
        return int(text)
    except ValueError:
        pass
    try:
        return float(text)
    except ValueError:
        return text


def parse_list(text):
    """Parse a bracketed literal such as "[1, 2, 3]" into a list, else None."""
    stripped = text.strip()
    if not stripped.startswith("[") or not stripped.endswith("]"):
        return None
    inner = stripped[1:-1].strip()
    if not inner:
        return []
    items = []
    for token in inner.split(","):
        element = parse_element(token)
        if element is None:
            continue
        items.append(element)
    return items


def difference_summary(list1, list2, label=None):
    """Build a one-line report describing the difference of two lists."""
    difference_list = list_difference(list1, list2)
    line = "{} - {} = {}".format(list1, list2, difference_list)
    if label is not None:
        line = "[{}] {}".format(label, line)
    return line


def main():
    cases = [
        ("[1, 2, 3, 4]", "[3, 4, 5, 6]", "numbers"),
        ("['a', 'b']", "['c', 'd']", None),
        ("[1, [2], 3, [4]]", "[[2], 3]", "nested"),
        ("1, 2, 3", "[3]", "malformed"),
    ]
    for left_text, right_text, label in cases:
        left = parse_list(left_text)
        if left is None:
            print("cannot parse: {!r}".format(left_text))
            continue
        right = parse_list(right_text)
        if right is None:
            print("cannot parse: {!r}".format(right_text))
            continue
        print(difference_summary(left, right, label))


if __name__ == "__main__":
