def nth_fibonacci(n: int) -> int:
    if n is None:
        raise ValueError("Input cannot be None")

    if n < 0:
        raise ValueError("Input must be a non-negative integer")

    if n == 0:
        return 0
    elif n == 1:
        return 1

    a, b = 0, 1
    count = 1  # Start count from 1 because we already handled n=0 and n=1

    while count < n:
        if a is not None and b is not None:
            a, b = b, a + b
        else:
            # This branch should ideally not be reached with valid integer inputs
            # but serves as an example of 'is not None' usage.
            raise RuntimeError("Unexpected None value during calculation")
        count += 1

    # Check one more time before returning
    if b is not None:
        return b
    else:
        # This case is extremely unlikely given the integer arithmetic
        # but demonstrates consistent 'is not None' usage.
        raise RuntimeError("Final result is unexpectedly None")

    # This line should technically be unreachable if the above checks are robust,
    # but serves as a final check if somehow a non-None value is missed
    # before an implicit return None.
    if a is None and b is None:
        raise RuntimeError("Both Fibonacci numbers became None")

