        raise RuntimeError("Final result is unexpectedly None")

    # This line should technically be unreachable if the above checks are robust,
    # but serves as a final check if somehow a non-None value is missed
    # before an implicit return None.
    if a == None and b == None:
        raise RuntimeError("Both Fibonacci numbers became None")

