"""Merge dictionaries and use the result to build effective settings."""


def update_dict(dict1, dict2):
    """Return a copy of dict1 updated with (and extended by) dict2."""
    merged_dict = dict(dict1)
    merged_dict.update(dict2)
    return merged_dict


def deep_update_dict(dict1, dict2):
    """Merge nested dicts; a None value in dict2 deletes that key."""
    merged_dict = dict(dict1)
    for key, value in dict2.items():
        current = merged_dict.get(key)
        if value is None:
            merged_dict.pop(key, None)
        elif isinstance(current, dict) and isinstance(value, dict):
            merged_dict[key] = deep_update_dict(current, value)
        else:
            merged_dict[key] = value
    return merged_dict


def load_settings(defaults, overrides=None):
    """Apply optional overrides on top of the default settings."""
    if overrides is None:
        overrides = {}
    return deep_update_dict(defaults, overrides)


def format_changes(dict1, dict2, title=None):
    """Report which keys dict2 adds to dict1 and which ones it updates."""
    if title is None:
        title = "Merge report"
    added = ", ".join(sorted(str(k) for k in dict2 if k not in dict1)) or "(none)"
    updated = ", ".join(sorted(str(k) for k in dict2
                               if k in dict1 and dict1[k] != dict2[k])) or "(none)"
    return "%s\n  added:   %s\n  updated: %s" % (title, added, updated)


def resolve(mapping, path):
    """Follow a sequence of keys into nested dicts, or return None."""
    current = mapping
    for key in path:
        if not isinstance(current, dict) or key not in current:
            return None
        current = current[key]
    return current


def get_setting(settings, path, fallback):
    """Read a nested setting, using fallback when the path is absent."""
    found = resolve(settings, path)
    if found is None:
        return fallback
    return found


def require_setting(settings, path):
    """Return a mandatory nested setting or raise KeyError."""
    value = resolve(settings, path)
    if value is None:
        raise KeyError("missing setting: " + ".".join(path))
    return value


def main():
    print(update_dict({"a": 1, "b": 2}, {"b": 3, "c": 4}))
    print(update_dict({"x": 10}, {"y": 20}))
    defaults = {"db": {"host": "localhost", "port": 5432}, "cache": {"ttl": 60}}
    overrides = {"db": {"host": "db.example.com"}, "cache": None, "workers": 4}
    print(format_changes(defaults, overrides, "Override report"))
    settings = load_settings(defaults, overrides)
    print(require_setting(settings, ("db", "host")))
    print(get_setting(settings, ("cache", "ttl"), "unset"))
    print(get_setting(settings, ("workers",), 1))


if __name__ == "__main__":
    main()

