from datetime import date, datetime


def parse_date(text):
    """Return a date for 'YYYY-MM-DD' text, or None when it is not a valid date."""
    if text is None:
        return None
    try:
        return datetime.strptime(text.strip(), '%Y-%m-%d').date()
    except ValueError:
        return None


def days_remaining(start_date_str, end_date_str):
    """Number of days between two 'YYYY-MM-DD' dates (end minus start)."""
    start = parse_date(start_date_str)
    if start is None:
        raise ValueError("invalid start date: %r" % (start_date_str,))
    end = parse_date(end_date_str)
    if end is None:
        raise ValueError("invalid end date: %r" % (end_date_str,))
    return (end - start).days


def describe_remaining(start_date_str, end_date_str, label=None):
    """Build a human readable line about the gap between two dates."""
    if label is None:
        label = "the target date"
    days = days_remaining(start_date_str, end_date_str)
    if days > 0:
        return "%d day(s) remaining until %s." % (days, label)
    if days == 0:
        return "Today is the day of %s." % label
    return "%s passed %d day(s) ago." % (label.capitalize(), -days)


def countdown_report(start_date_str, events):
    """Sort valid events by remaining days and render one report line for each."""
    rows = []
    bad = []
    for label, when in events:
        if parse_date(when) is None:
            bad.append("%-14s %s  (unparsable date)" % (label, when))
        else:
            rows.append((days_remaining(start_date_str, when), label, when))
    rows.sort()
    lines = ["%-14s %s  %+5d" % (label, when, days) for days, label, when in rows]
    return "\n".join(lines + bad)


def main():
    print(days_remaining('2023-01-01', '2023-01-05'))
    print(days_remaining('2023-12-31', '2024-01-01'))

    today = date.today()
    start = today.isoformat()
    events = [
        ("New Year", "%d-01-01" % (today.year + 1)),
        ("Mid-summer", "%d-06-21" % today.year),
        ("Deadline", "%d-12-15" % today.year),
        ("Typo", "%d-02-30" % today.year),
    ]
    print(countdown_report(start, events))

    for label, when in events:
        target = parse_date(when)
        if target is None:
            print("skipping %s: %r is not a date" % (label, when))
        else:
            print(describe_remaining(start, target.isoformat(), label))
    print(describe_remaining(start, start))


if __name__ == '__main__':
    main()

