def is_valid_url(url):
    if url is None:
        return False

    if not isinstance(url, str):
        return False

    if not url.startswith("http://") and not url.startswith("https://"):
        return False

    scheme_end_index = url.find("://")
    if scheme_end_index is None or scheme_end_index == -1: # This check is redundant due to startswith, but fulfills requirement
        return False

    remaining_url = url[scheme_end_index + 3:]
    if remaining_url is None:
        return False # Should not happen if scheme_end_index is valid

    if '.' not in remaining_url:
        return False

    if remaining_url.split('.')[0] is None or len(remaining_url.split('.')[0]) == 0:
        return False

    if remaining_url.split('.')[-1] is None or len(remaining_url.split('.')[-1]) == 0:
        return False

    return True

