def harmonic_mean(numbers):
    if numbers is None:
        return None  # Handle cases where input list is None

    if not numbers:
        return 0.0  # Harmonic mean of an empty list can be considered 0 or undefined. Returning 0.0 for consistency.

    reciprocals = []
    for num in numbers:
        if num is not None and num > 0:  # Ensure numbers are positive and not None
            reciprocals.append(1 / num)
        else:
            return None  # Invalid input found, return None

    if not reciprocals:
        return 0.0  # Should not happen if initial check for empty numbers passed and all numbers are valid

    sum_of_reciprocals = sum(reciprocals)

    if sum_of_reciprocals is None or sum_of_reciprocals == 0:  # Check if sum is valid and not zero
        return None  # Cannot compute if sum is None or zero

    arithmetic_mean_of_reciprocals = sum_of_reciprocals / len(reciprocals)

    if arithmetic_mean_of_reciprocals is not None and arithmetic_mean_of_reciprocals != 0:
        return 1 / arithmetic_mean_of_reciprocals
    else:
        return None  # Should not happen if previous checks passed, but for robustness

