def parse_dimension(text):
    """Convert a text field into a positive float, or None if it is unusable."""
    cleaned = text.strip()
    if not cleaned:
        return None
    try:
        value = float(cleaned)
    except ValueError:
        return None
    if value <= 0:
        return None
    return value


def rectangle_area(width, height):
    """Return the area of a rectangle with the given width and height."""
    return float(width) * float(height)


def rectangle_perimeter(width, height):
    return 2.0 * (float(width) + float(height))


def parse_record(line):
    """Parse 'name,width,height' into a dict, or None when the line is invalid."""
    parts = line.split(",")
    if len(parts) != 3:
        return None
    name = parts[0].strip()
    width = parse_dimension(parts[1])
    if width is None:
        return None
    height = parse_dimension(parts[2])
    if height is None:
        return None
    return {"name": name or "unnamed", "width": width, "height": height}


def describe(record, unit=None):
    suffix = "" if unit is None else " " + unit
    area = rectangle_area(record["width"], record["height"])
    perimeter = rectangle_perimeter(record["width"], record["height"])
    return "{0}: {1:g}{3} x {2:g}{3} -> area {4:.2f}, perimeter {5:.2f}".format(
        record["name"], record["width"], record["height"], suffix, area, perimeter
    )


def summarize(lines, unit=None):
    """Build a report for every parsable line plus the total area."""
    report = []
    total = None
    for number, line in enumerate(lines, start=1):
        record = parse_record(line)
        if record is None:
            report.append("line {0}: skipped ({1!r})".format(number, line.strip()))
            continue
        report.append(describe(record, unit))
        area = rectangle_area(record["width"], record["height"])
        if total is None:
            total = area
        else:
            total += area
    if total is None:
        report.append("no valid rectangles found")
    else:
        report.append("total area: {0:.2f}".format(total))
    return report


def main():
    print(rectangle_area(5, 10))
    print(rectangle_area(2.5, 4))
    data = [
        "kitchen tile,5,10",
        "card,2.5,4",
        "broken,abc,4",
        "window,1.2,0.8",
        "bad line",
    ]
    for entry in summarize(data, unit="cm"):
        print(entry)


if __name__ == "__main__":
    main()

