    "sedentary": 1.2,
    "light": 1.375,
    "moderate": 1.55,
    "active": 1.725,
    "very_active": 1.9,
}

GENDER_OFFSETS = {"male": 5.0, "female": -161.0}


def calculate_bmr(gender, weight_kg, height_cm, age_years):
    """Mifflin-St Jeor: 10*kg + 6.25*cm - 5*years, then +5 male / -161 female."""
    if gender is None:
        raise ValueError("gender is required")
    offset = GENDER_OFFSETS.get(gender.strip().lower())
    if offset is None:
        raise ValueError("gender must be 'male' or 'female'")
    for name, value in (("weight_kg", weight_kg), ("height_cm", height_cm),
                        ("age_years", age_years)):
        if value is None:
            raise ValueError(name + " is required")
        if value <= 0:
            raise ValueError(name + " must be positive")
    return 10.0 * weight_kg + 6.25 * height_cm - 5.0 * age_years + offset


def daily_energy_needs(bmr, activity_level=None):
    if activity_level is None:
        factor = ACTIVITY_FACTORS["sedentary"]
    else:
        factor = ACTIVITY_FACTORS.get(activity_level.strip().lower())
        if factor is None:
            raise ValueError("unknown activity level: " + activity_level)
    return bmr * factor


def parse_person(line):
    parts = [p.strip() for p in line.split(",")]
    if len(parts) < 4:
