    activity = parts[4] if len(parts) > 4 and parts[4] else None
    try:
        return {
            "gender": parts[0],
            "weight_kg": float(parts[1]),
            "height_cm": float(parts[2]),
            "age_years": int(parts[3]),
            "activity": activity,
        }
    except ValueError:
        return None


def format_report(person):
    bmr = calculate_bmr(person["gender"], person["weight_kg"],
                        person["height_cm"], person["age_years"])
    activity = person.get("activity")
    tdee = daily_energy_needs(bmr, activity)
    label = "sedentary (assumed)" if activity is None else activity
    return "{0}, {1:.0f} kg, {2:.0f} cm, {3} y -> BMR {4:.1f} kcal/day, {5}: {6:.1f} kcal/day".format(
