import re
import sys
from collections import Counter

MENTION_RE = re.compile(r'@(\w+)')


def extract_mentions(text):
    """Return the list of mentions (without '@') found in text."""
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    return MENTION_RE.findall(text)


def first_mention(text):
    """Return the first mention in text, or None when there is none."""
    match = MENTION_RE.search(text)
    if match is None:
        return None
    return match.group(1)


def read_text(path):
    """Read the text to scan from path, or from stdin when path is None."""
    if path is None:
        return sys.stdin.read()
    with open(path, encoding="utf-8") as handle:
        return handle.read()


def mention_counts(text):
    """Map each mentioned name to how many times it appears."""
    return Counter(extract_mentions(text))


def unique_mentions(text):
    """Return mentions in order of first appearance, without duplicates."""
    return list(mention_counts(text))


def most_mentioned(text):
    """Return the most frequently mentioned name, or None if there are none."""
    counts = mention_counts(text)
    if not counts:
        return None
    return counts.most_common(1)[0][0]


def format_report(text, label=None):
    """Build a human readable summary of the mentions inside text."""
    if label is None:
        label = "stdin"
    mentions = extract_mentions(text)
    lines = ["%s: %d mention(s)" % (label, len(mentions))]
    lead = first_mention(text)
    if lead is not None:
        lines.append("  first: @" + lead)
    top = most_mentioned(text)
    if top is not None:
        lines.append("  top: @%s (%d)" % (top, mention_counts(text)[top]))
    uniques = unique_mentions(text)
    if uniques:
        lines.append("  unique: " + ", ".join("@" + u for u in uniques))
    return "\n".join(lines)


def main():
    path = sys.argv[1] if len(sys.argv) > 1 else None
    print(format_report(read_text(path), path))


if __name__ == "__main__":
    main()

