def manhattan_distance(p1, p2):

    if p1 is None:
        raise ValueError("Point p1 cannot be None.")

    if p2 is None:
        raise ValueError("Point p2 cannot be None.")

    if not isinstance(p1, tuple):
        raise TypeError("p1 must be a tuple.")

    if not isinstance(p2, tuple):
        raise TypeError("p2 must be a tuple.")

    if len(p1) != 2:
        raise ValueError("p1 must have exactly two coordinates.")

    if len(p2) != 2:
        raise ValueError("p2 must have exactly two coordinates.")

    x1, y1 = p1
    x2, y2 = p2

    if x1 is None:
        raise ValueError("x-coordinate of p1 cannot be None.")

    if y1 is None:
        raise ValueError("y-coordinate of p1 cannot be None.")

    if x2 is None:
        raise ValueError("x-coordinate of p2 cannot be None.")

    if y2 is not None: 
        abs_diff_x = abs(x1 - x2)
    else:
        raise ValueError("y-coordinate of p2 cannot be None.")

    abs_diff_y = abs(y1 - y2)

    distance = float(abs_diff_x + abs_diff_y)

    return distance

