def parse_number(text):
    """Return the integer described by text, or None when it is not an integer."""
    if text is None:
        return None
    stripped = text.strip()
    if not stripped:
        return None
    try:
        return int(stripped)
    except ValueError:
        return None


def sort_digits(number):
    """Return a new integer whose digits are those of `number` in ascending order."""
    if number is None:
        raise TypeError("number must be an int, not None")
    if isinstance(number, bool) or not isinstance(number, int):
        raise TypeError("number must be an int")
    negative = number < 0
    digits = sorted(str(abs(number)))
    sorted_number = int("".join(digits))
    if negative:
        sorted_number = -sorted_number
    return sorted_number


def sort_digits_text(text):
    """Sort the digits of a textual number, returning None if the text is unusable."""
    number = parse_number(text)
    if number is None:
        return None
    return sort_digits(number)


def format_report(text, sorted_number=None):
    """Describe one conversion; a missing result means the input was rejected."""
    if sorted_number is None:
        return "%-12s -> invalid integer" % text
    return "%-12s -> %d" % (text, sorted_number)


