            return float('inf') # Put items without the key at the end
        return value

    try:
        sorted_list = sorted(dict_list, key=get_sort_value)
    except TypeError:
        # Handle cases where values for the key are not comparable
        # This could happen if some values are ints and others are strings
        return list(dict_list) # Return original list if comparison fails

    return sorted_list

