import argparse
import random

FACES = ('Heads', 'Tails')


def simulate_coin_flip(rng=None):
    """Return 'Heads' or 'Tails' chosen at random."""
    if rng is None:
        rng = random
    result = rng.choice(FACES)
    return result


def make_rng(seed=None):
    """Build a random source; a seed makes the run reproducible."""
    if seed is None:
        return random
    return random.Random(seed)


def flip_many(count, rng=None):
    """Return a list of `count` flip results."""
    if count < 0:
        raise ValueError('count must be non-negative')
    if rng is None:
        rng = random
    return [simulate_coin_flip(rng) for _ in range(count)]


def tally(results):
    """Count how often each face appeared."""
    counts = {face: 0 for face in FACES}
    for result in results:
        if counts.get(result) is None:
            raise ValueError('unexpected flip result: %r' % (result,))
        counts[result] += 1
    return counts


def longest_streak(results):
    """Return (face, length) for the longest run, or (None, 0) if empty."""
    best_face, best_length = None, 0
    current_face, current_length = None, 0
    for result in results:
        if current_face is not None and result == current_face:
            current_length += 1
        else:
            current_face, current_length = result, 1
        if current_length > best_length:
            best_face, best_length = current_face, current_length
    return best_face, best_length


def format_report(results):
    """Build a human readable summary of a sequence of flips."""
    if not results:
        return 'No flips performed.'
    counts = tally(results)
    total = len(results)
    lines = ['Flips: %d' % total]
    for face in FACES:
        share = 100.0 * counts[face] / total
        lines.append('  %-5s %4d  (%5.1f%%)' % (face, counts[face], share))
    face, length = longest_streak(results)
    if face is not None:
        lines.append('Longest streak: %d x %s' % (length, face))
    return '\n'.join(lines)


def main(argv=None):
    parser = argparse.ArgumentParser(description='Simulate coin flips.')
    parser.add_argument('-n', '--count', type=int, default=1)
    parser.add_argument('-s', '--seed', type=int, default=None)
    args = parser.parse_args(argv)

    rng = make_rng(args.seed)
    if args.count == 1:
        print(simulate_coin_flip(rng))
    else:
        results = flip_many(args.count, rng)
        print(format_report(results))
    return 0


if __name__ == '__main__':
    raise SystemExit(main())

