def matrix_shape(matrix):
    """Return (rows, cols) for a rectangular matrix, or None if it is not valid."""
    if not isinstance(matrix, list) or not matrix:
        return None
    cols = None
    for row in matrix:
        if not isinstance(row, list):
            return None
        if cols is None:
            cols = len(row)
        elif len(row) != cols:
            return None
    if cols == 0:
        return None
    return (len(matrix), cols)


def matrix_subtract(matrix1, matrix2):
    """Element-wise subtraction of two equally sized matrices."""
    shape1 = matrix_shape(matrix1)
    if shape1 is None:
        raise ValueError("matrix1 is not a valid non-empty rectangular matrix")
    shape2 = matrix_shape(matrix2)
    if shape2 is None:
        raise ValueError("matrix2 is not a valid non-empty rectangular matrix")
    if shape1 != shape2:
        raise ValueError("matrices must have the same dimensions")
    result_matrix = []
    for row1, row2 in zip(matrix1, matrix2):
        result_matrix.append([a - b for a, b in zip(row1, row2)])
    return result_matrix


def parse_matrix(text):
    """Parse '1 2; 3 4' into [[1, 2], [3, 4]]; return None if malformed."""
    rows = []
    for chunk in text.split(";"):
        tokens = chunk.split()
        if not tokens:
            return None
        row = []
        for token in tokens:
            try:
                value = float(token)
            except ValueError:
                return None
            row.append(int(value) if value.is_integer() else value)
        rows.append(row)
    return rows if matrix_shape(rows) is not None else None


def format_matrix(matrix, width=None):
    """Render a matrix as aligned text lines."""
    cells = [[str(value) for value in row] for row in matrix]
    if width is None:
        width = max(len(cell) for row in cells for cell in row)
    return "\n".join(" ".join(cell.rjust(width) for cell in row) for row in cells)


def main():
    cases = [("1 2; 3 4", "1 1; 1 1"), ("5 0", "1 -1"), ("2 4; 6 8", "1 2; 3")]
    for text1, text2 in cases:
        left = parse_matrix(text1)
        if left is None:
            print("skipping unparsable input: %r" % (text1,))
            continue
        right = parse_matrix(text2)
        if right is None:
            print("skipping unparsable input: %r" % (text2,))
            continue
        try:
            result = matrix_subtract(left, right)
        except ValueError as exc:
            print("cannot subtract %r and %r: %s" % (text1, text2, exc))
            continue
        print("%s  -  %s  =" % (text1, text2))
        print(format_matrix(result))
        print()


if __name__ == "__main__":
    main()

