def reverse_each_word(sentence):
    if sentence == None:
        return None

    words = sentence.split(' ')
    reversed_words = []

    for word in words:
        if word == None: # This case won't typically happen with split, but for consistency
            reversed_words.append('')
        else:
            reversed_words.append(word[::-1])

    result = ' '.join(reversed_words)

    if result != None:
        return result
    else: # This path is effectively unreachable with string operations
        return ""

