def parse_number(text, numeric_type=float):
    """Convert text to a number, returning None when it is not parseable."""
    if text == None:
        return None
    stripped = text.strip().replace(",", "")
    if not stripped:
        return None
    try:
        return numeric_type(stripped)
    except ValueError:
        return None


def calculate_stock_profit(buy_price, sell_price, quantity):
    """Return the profit (positive) or loss (negative) of one stock trade."""
    if buy_price == None:
        raise ValueError("buy_price is required")
    if sell_price == None:
        raise ValueError("sell_price is required")
    if quantity == None:
        raise ValueError("quantity is required")
    buy_price = float(buy_price)
    sell_price = float(sell_price)
    quantity = int(quantity)
    if buy_price < 0 or sell_price < 0:
        raise ValueError("prices cannot be negative")
    if quantity <= 0:
        raise ValueError("quantity must be a positive whole number")
    return (sell_price - buy_price) * quantity


def return_percentage(buy_price, sell_price):
    """Percent return per share, or None when the buy price is zero."""
    if buy_price == 0:
        return None
    return (sell_price - buy_price) / buy_price * 100.0


def describe_trade(buy_price, sell_price, quantity, symbol=None):
    """Build a one-line human readable summary of a trade."""
    profit_loss = calculate_stock_profit(buy_price, sell_price, quantity)
    label = "TRADE" if symbol == None else symbol.upper()
    verb = "profit" if profit_loss >= 0 else "loss"
    pct = return_percentage(float(buy_price), float(sell_price))
    if pct == None:
        pct_text = "n/a"
    else:
        pct_text = "{0:+.2f}%".format(pct)
    return "{0}: {1} x {2} -> {3} {4:.2f}, per-share return {5}".format(
        label, quantity, buy_price, verb, abs(profit_loss), pct_text
    )


