    if hex_string is None:
        return 0

    decimal_value = 0
    power = 0

    # Handle empty string
    if hex_string == '':
        return 0

    for char in reversed(hex_string):
        if char is None: # This case is unlikely with string iteration but included for demonstration
            continue

        char_upper = char.upper()

        if '0' <= char_upper <= '9':
            digit = int(char_upper)
        elif 'A' <= char_upper <= 'F':
            digit = ord(char_upper) - ord('A') + 10
        else:
            # Handle invalid characters, could raise ValueError or return 0
            if hex_string is not None: # Another example of checking
