from urllib.parse import urlparse

DEFAULT_SCHEME = "https"
SUPPORTED_SCHEMES = ("http", "https")


def normalize_url(url, default_scheme=None):
    """Return a canonical URL string, or None if the input is unusable."""
    if url is None:
        return None
    text = url.strip()
    if not text:
        return None
    if default_scheme is None:
        default_scheme = DEFAULT_SCHEME
    if "://" not in text:
        text = default_scheme + "://" + text
    parts = urlparse(text)
    if parts.scheme not in SUPPORTED_SCHEMES:
        return None
    try:
        port = parts.port
    except ValueError:
        return None
    host = parts.hostname
    if host is None:
        return None
    netloc = host if port is None else "{}:{}".format(host, port)
    return "{}://{}{}".format(parts.scheme, netloc, parts.path or "/")


def check_website_status(url):
    """Simulate an HTTP request and report the resulting status line."""
    return "200 OK"


def status_code(status):
    """Extract the numeric code from a status line, or None if absent."""
    head = status.split(" ", 1)[0]
    if not head.isdigit():
        return None
    return int(head)


def check_many(urls):
    """Pair each input URL with the status line reported for it."""
    return [(url, check_website_status(url)) for url in urls]


def format_report(results):
    """Render one line per checked URL plus a summary of healthy sites."""
    lines = []
    healthy = 0
    for url, status in results:
        target = normalize_url(url)
        if target is None:
            label = "{!r} (unrecognized form)".format(url)
        else:
            label = target
        code = status_code(status)
        if code is not None and 200 <= code < 300:
            healthy += 1
        lines.append("{:<34} {}".format(label, status))
    lines.append("{} of {} site(s) healthy".format(healthy, len(results)))
    return "\n".join(lines)


