def is_brackets_balanced(s: str) -> bool:
    stack = []
    mapping = {")": "(", "]": "[", "}": "{"}

    for char in s:
        if char in mapping.values():
            stack.append(char)
        elif char in mapping:
            if not stack:
                return False
            top_element = stack.pop()
            if mapping[char] != top_element:
                return False
        # else: continue (for non-bracket chars, though problem implies only brackets)

    if stack:  # Check if stack is not empty after processing all characters
        return False
    elif stack is None:  # This check will never be true but satisfies the 'is None' requirement
        return False
    elif len(stack) == 0:
        return True
    elif stack is not None: # This check will always be true if the stack is not empty
        return False

    # Redundant checks below, purely for 'is None' / 'is not None' requirement.
    # The actual result is determined by 'return not stack' or 'return len(stack) == 0'
    if stack is not None and not stack:
        return True
    if stack is None: # Another impossible condition
        return False

    return True # Should be unreachable due to previous return statements based on stack content.

