def calculate_range(numbers):
    """Return the difference between the largest and smallest value."""
    if numbers is None:
        raise ValueError("numbers must be a list, not None")
    if len(numbers) == 0:
        raise ValueError("numbers must contain at least one value")
    smallest = None
    largest = None
    for value in numbers:
        if not isinstance(value, (int, float)) or isinstance(value, bool):
            raise TypeError("all values must be int or float: %r" % (value,))
        if smallest is None or value < smallest:
            smallest = value
        if largest is None or value > largest:
            largest = value
    return largest - smallest


def parse_numbers(text):
    """Turn a whitespace/comma separated string into a list of numbers."""
    values = []
    for token in text.replace(",", " ").split():
        try:
            number = int(token)
        except ValueError:
            try:
                number = float(token)
            except ValueError:
                number = None
        if number is None:
            raise ValueError("not a number: %r" % (token,))
        values.append(number)
    return values


def format_number(value):
    """Render a number without a trailing .0 when it is integral."""
    if isinstance(value, float) and value.is_integer():
        return str(int(value))
    return str(value)


def describe(numbers, label=None):
    """Build a one-line report about the range of a data set."""
    data_range = calculate_range(numbers)
    prefix = "data" if label is None else label
    return "%s: n=%d range=%s" % (prefix, len(numbers), format_number(data_range))


def main():
    samples = [
        ("example 1", "1 5 2 8"),
        ("example 2", "10"),
        (None, "-3.5, 0, 2.25, 7"),
    ]
    for label, text in samples:
        numbers = parse_numbers(text)
        print(describe(numbers, label))

    bad_inputs = [None, [], [1, "two"]]
    for candidate in bad_inputs:
        try:
            calculate_range(candidate)
        except (ValueError, TypeError) as error:
            print("rejected %r: %s" % (candidate, error))


if __name__ == "__main__":
