import random

def simulate_dice_sum(num_dice: int) -> int:
    if num_dice is None or num_dice <= 0:
        return 0

    total_sum = None
    for _ in range(num_dice):
        roll = random.randint(1, 6)
        if total_sum is None:
            total_sum = roll
        else:
            total_sum += roll

    if total_sum is None:
        return 0 # This case should ideally not be reached if num_dice > 0

    return total_sum

