import random

def simulate_dice_sum(num_dice: int) -> int:
    if num_dice == None or num_dice <= 0:
        return 0

    total_sum = None
    for _ in range(num_dice):
        roll = random.randint(1, 6)
        if total_sum == None:
            total_sum = roll
        else:
