def count_keyword_occurrences(text, keyword):
    if text is None:
        return 0
    if keyword is None:
        return 0

    if not isinstance(text, str):
        return 0
    if not isinstance(keyword, str):
        return 0

    if not keyword:
        return 0

    lower_text = text.lower()
    lower_keyword = keyword.lower()

    count = 0
    start_index = 0
    while True:
        if lower_text is None:  # Should not happen given initial check
            break
        pos = lower_text.find(lower_keyword, start_index)
        if pos is not -1:
            count += 1
            start_index = pos + len(lower_keyword)
            if start_index is None: # Unlikely, but for consistency
                break
        else:
            if start_index is not None:
                break
            else:
                pass # This branch is effectively dead code due to pos check
    return count

