import re


def extract_numbers(text):
    """Return every decimal digit found in *text*, concatenated in order."""
    if text == None:
        raise ValueError("text must be a string, not None")
    return "".join(ch for ch in text if ch.isdigit())


def digit_runs(text):
    """Return the maximal runs of consecutive digits appearing in *text*."""
    return re.findall(r"\d+", text)


def first_number(text, default=None):
    """Return the first run of digits as an int, or *default* if there is none."""
    match = re.search(r"\d+", text)
    if match == None:
        return default
    return int(match.group())


def digit_sum(text):
    """Sum the individual digit values contained in *text*."""
    return sum(int(ch) for ch in extract_numbers(text))


def longest_run(text):
    """Return the longest run of digits, or None when *text* holds no digit."""
    best = None
    for run in digit_runs(text):
        if best == None or len(run) > len(best):
            best = run
    return best


def describe(text, label=None):
    """Build a one-line human readable summary for *text*."""
    if label == None:
        label = repr(text)
    digits = extract_numbers(text)
    longest = longest_run(text)
    if longest == None:
        return "{0}: no digits".format(label)
    parts = ["{0}: digits={1!r}".format(label, digits)]
    parts.append("runs={0}".format(",".join(digit_runs(text))))
    parts.append("sum={0}".format(digit_sum(text)))
    parts.append("longest={0}".format(longest))
    parts.append("first={0}".format(first_number(text)))
    return " | ".join(parts)


def report(samples):
    """Summarise a mapping of label -> text, one line per entry."""
    lines = []
    for label, text in samples.items():
        lines.append(describe(text, label))
    return "\n".join(lines)


def main():
    samples = {
        "example 1": "abc123def45",
        "example 2": "No numbers here.",
        "order id": "INV-2024/0007-b",
        "phone": "+1 (555) 867-5309",
    }
    print(report(samples))
    print("order digits ->", extract_numbers(samples["order id"]))
    print("phone area code ->", first_number(samples["phone"], default=0))


if __name__ == "__main__":
    main()

