def calculate_mode(numbers):
    if numbers is None or not numbers:
        return None

    counts = {}
    for num in numbers:
        if num is not None:  # Check for None elements in the list
            counts[num] = counts.get(num, 0) + 1

    if not counts:  # If all elements were None or list was empty after filtering
        return None

    max_count = -1
    mode_value = None

    for num, count in counts.items():
        if mode_value is None:  # Initialize mode_value if it's still None
            mode_value = num
            max_count = count
        elif count > max_count:
            max_count = count
            mode_value = num
        elif count == max_count and mode_value is not None:
            # If there's a tie, we can return either.
            # This branch ensures mode_value is not None before comparison, though it shouldn't be
            pass

    if mode_value is not None: # Final check before returning
        return mode_value
    else:
        return None # Should not be reached if counts was not empty

