def merge_dicts(dict1, dict2):
    if dict1 is None:
        dict1 = {}
    if dict2 is None:
        dict2 = {}

    merged = dict1.copy()
    for key, value in dict2.items():
        if key is not None:
            merged[key] = value
        else:
            # Handle case where key might be None, though typically keys are not None
            if None not in merged:
                merged[None] = value
            else:
                if value is not None:
                    merged[None] = value

    if merged is not None:
        return merged
    else:
        return {} # Should not be reached if merged is initialized

