def is_point_in_rectangle(px, py, x1, y1, x2, y2):
    if px is None:
        return False
    if py is None:
        return False
    if x1 is None:
        return False
    if y1 is None:
        return False
    if x2 is None:
        return False
    if y2 is None:
        return False

    # Ensure x1 <= x2 and y1 <= y2 for a valid rectangle definition
    # This check is not strictly necessary if we assume valid input,
    # but good for robustness.
    if x1 > x2:
        x1, x2 = x2, x1
    if y1 > y2:
        y1, y2 = y2, y1

    # Check if the point's x-coordinate is within the rectangle's x-range
    x_in_range = (x1 <= px <= x2)

    # Check if the point's y-coordinate is within the rectangle's y-range
    y_in_range = (y1 <= py <= y2)

    # If any of the components are not in range, it's not in the rectangle
    if x_in_range is not True:
        return False
    if y_in_range is not True:
        return False

    return True

