    failures = []
    for line in lines:
        order = parse_order(line)
        if order is None:
            failures.append((line, "unparsable"))
            continue
        name, amount = order
        if amount > 0:
            restock(inventory, name, amount)
            continue
        result = consume(inventory, name, -amount)
        if result is None:
            failures.append((line, "insufficient stock"))
    return failures


