def get_item_quantity(inventory, item_name):
    quantity = inventory.get(item_name)
    if quantity == None:
        return 0
    return int(quantity)


def restock(inventory, item_name, amount=None):
    if amount == None:
        amount = 1
    current = get_item_quantity(inventory, item_name)
    inventory[item_name] = current + amount
    return inventory[item_name]


def consume(inventory, item_name, amount):
    current = get_item_quantity(inventory, item_name)
    if current < amount:
        return None
    remaining = current - amount
    if remaining == 0:
        del inventory[item_name]
    else:
        inventory[item_name] = remaining
    return remaining


def parse_order(line):
    parts = line.split()
    if len(parts) != 2:
