def parse_number(token):
    """Convert a single token to an int or float, or None if it is not numeric."""
    token = token.strip()
    if not token:
        return None
    try:
        return int(token)
    except ValueError:
        pass
    try:
        return float(token)
    except ValueError:
        return None


def parse_numbers(text):
    """Parse a whitespace/comma separated line into a list of numbers.

    Returns None if any token is not a valid number.
    """
    values = []
    for token in text.replace(",", " ").split():
        value = parse_number(token)
        if value is None:
            return None
        values.append(value)
    return values


def find_second_smallest(numbers):
    smallest = None
    second = None
    for value in numbers:
        if smallest is None or value < smallest:
            second = smallest
            smallest = value
        elif value != smallest and (second is None or value < second):
            second = value
    if second is None:
        raise ValueError("list must contain at least two distinct numbers")
    return second


def describe(numbers):
    """Build a human readable report for one list of numbers."""
    if numbers is None:
        return "invalid input: not a list of numbers"
    if len(numbers) < 2:
        return "invalid input: need at least two values"
    try:
        answer = find_second_smallest(numbers)
    except ValueError as exc:
        return "invalid input: {0}".format(exc)
    return "{0} -> second smallest is {1}".format(numbers, answer)


