def validate_matrix(matrix):
    """Return the common row length of matrix, or None for an empty matrix."""
    if matrix is None:
        raise ValueError("matrix must not be None")
    if not isinstance(matrix, list):
        raise TypeError("matrix must be a list of lists")
    width = None
    for index, row in enumerate(matrix):
        if row is None:
            raise ValueError("row %d must not be None" % index)
        if not isinstance(row, list):
            raise TypeError("row %d must be a list" % index)
        if width is None:
            width = len(row)
        elif len(row) != width:
            raise ValueError("row %d has length %d, expected %d" % (index, len(row), width))
    return width


def transpose_matrix(matrix):
    """Return the transpose of a rectangular 2D matrix as a new list of lists."""
    width = validate_matrix(matrix)
    if width is None:
        return []
    return [[row[col] for row in matrix] for col in range(width)]


def cell_width(matrix):
    """Return the widest rendered cell in matrix, or None if there are no cells."""
    widest = None
    for row in matrix:
        for value in row:
            length = len(str(value))
            if widest is None or length > widest:
                widest = length
    return widest


def format_matrix(matrix, pad=None):
    """Render matrix as aligned text lines; pad defaults to the widest cell."""
    if pad is None:
        pad = cell_width(matrix)
    if pad is None:
        return "(empty)"
    lines = []
    for row in matrix:
        lines.append(" ".join(str(value).rjust(pad) for value in row))
    return "\n".join(lines)


def parse_matrix(text):
    """Parse rows like '1 2 3;4 5 6' into a matrix, or None if text is blank."""
    stripped = text.strip()
    if not stripped:
        return None
    matrix = []
    for chunk in stripped.split(";"):
        matrix.append([float(token) if "." in token else int(token)
                       for token in chunk.split()])
    return matrix


def report(source):
    """Print a matrix and its transpose, accepting text or an actual matrix."""
    if isinstance(source, str):
        matrix = parse_matrix(source)
        if matrix is None:
            print("no matrix given")
            return
    else:
        matrix = source
    pad = cell_width(matrix)
    print("original:")
    print(format_matrix(matrix, pad))
    print("transposed:")
    print(format_matrix(transpose_matrix(matrix), pad))
    print("-" * 20)


def main():
    report([[1, 2, 3], [4, 5, 6]])
    report([[10]])
    report("1 2;3 4;5 6")
    report("  ")
    report([])


if __name__ == "__main__":
    main()

