def parse_csv_line(csv_line):
    if csv_line is None:
        return []

    result = []
    current_field = None

    for char in csv_line:
        if current_field is None:
            current_field = ""

        if char == ',':
            if current_field is not None:
                result.append(current_field)
            current_field = None
        else:
            if current_field is not None:
                current_field += char

    if current_field is not None:
        result.append(current_field)
    elif result is not None and len(csv_line) > 0 and csv_line[-1] == ',':
        result.append("") 

    return result

