def calculate_simple_interest(principal, rate, time):
    """Return the simple interest earned on `principal` at `rate`% for `time` years."""
    if principal < 0 or rate < 0 or time < 0:
        raise ValueError("principal, rate and time must be non-negative")
    return float(principal) * float(rate) * int(time) / 100.0


def parse_number(text, allow_float=True):
    """Convert a user-supplied string to a number, or None when it is not numeric."""
    if text is None:
        return None
    cleaned = text.strip().replace(",", "")
    if not cleaned:
        return None
    try:
        return float(cleaned) if allow_float else int(cleaned)
    except ValueError:
        return None


def parse_loan_record(line):
    """Parse 'principal,rate,years' into a tuple, or None if the line is unusable."""
    parts = line.split(",")
    if len(parts) != 3:
        return None
    principal = parse_number(parts[0])
    if principal is None:
        return None
    rate = parse_number(parts[1])
    if rate is None:
        return None
    years = parse_number(parts[2], allow_float=False)
    if years is None:
        return None
    return principal, rate, years


def build_schedule(principal, rate, time):
    """Year-by-year list of (year, interest so far, total amount)."""
    schedule = []
    for year in range(1, int(time) + 1):
        interest = calculate_simple_interest(principal, rate, year)
        schedule.append((year, interest, principal + interest))
    return schedule


def format_record(record):
    """Render one parsed record as a report line."""
    if record is None:
        return "  <skipped: malformed record>"
    principal, rate, years = record
    interest = calculate_simple_interest(principal, rate, years)
    return "  {:10.2f} @ {:5.2f}% for {:>2} yr -> interest {:10.2f}".format(
        principal, rate, years, interest)


def main():
    records = ["1000, 5, 2", "500, 2.5, 10", "2,500.00, 3.75, 4", "oops, 5, 1"]
    print("Simple interest report")
    for line in records:
        print(format_record(parse_loan_record(line)))

    longest = None
    for line in records:
        record = parse_loan_record(line)
        if record is None:
            continue
        if longest is None or record[2] > longest[2]:
            longest = record
    if longest is not None:
        print("Schedule for the longest term ({} years):".format(longest[2]))
        for year, interest, total in build_schedule(*longest):
            print("  year {:>2}: interest {:8.2f}, total {:10.2f}".format(
                year, interest, total))


if __name__ == "__main__":
    main()

