HEX_DIGITS = "0123456789ABCDEF"


def digit_value(char):
    """Return the numeric value of a single hex digit, or None if invalid."""
    index = HEX_DIGITS.find(char.upper())
    if index < 0:
        return None
    return index


def normalize_hex(hex_string):
    """Strip whitespace and an optional 0x/0X prefix; return None if malformed."""
    if hex_string is None:
        return None
    text = hex_string.strip()
    sign = ""
    if text[:1] in ("+", "-"):
        sign = text[0]
        text = text[1:]
    if text[:2].lower() == "0x":
        text = text[2:]
    if not text:
        return None
    for char in text:
        if digit_value(char) is None:
            return None
    return sign + text.upper()


def hex_to_decimal(hex_string):
    cleaned = normalize_hex(hex_string)
    if cleaned is None:
        raise ValueError("not a valid hexadecimal number: %r" % (hex_string,))
    negative = cleaned[0] == "-"
    if cleaned[0] in ("+", "-"):
        cleaned = cleaned[1:]
    total = 0
    for char in cleaned:
        total = total * 16 + HEX_DIGITS.index(char)
    return -total if negative else total


def try_convert(hex_string):
    """Convert without raising; return None when the input is unusable."""
    if normalize_hex(hex_string) is None:
        return None
    return hex_to_decimal(hex_string)


def report(inputs):
    lines = []
    for item in inputs:
        result = try_convert(item)
        if result is None:
            lines.append("%-10s -> invalid" % (repr(item),))
        else:
            lines.append("%-10s -> %d" % (repr(item), result))
    return "\n".join(lines)


def main():
    import sys

    arguments = sys.argv[1:]
    if arguments:
        print(report(arguments))
    else:
        print(report(["A", "1A", "0xff", " 7de ", "-2B", "", "G1", None]))


if __name__ == "__main__":
    main()

