def is_palindromic_number(number):
    """Return True if the integer reads the same forwards and backwards."""
    if isinstance(number, bool) or not isinstance(number, int):
        raise TypeError("number must be an int")
    digits = str(abs(number))
    return digits == digits[::-1]


def parse_number(text):
    """Convert a string to an int, or return None if it is not a valid integer."""
    if text is None:
        return None
    stripped = text.strip()
    if not stripped:
        return None
    try:
        return int(stripped)
    except ValueError:
        return None


def next_palindrome(number, limit=None):
    """Smallest palindrome strictly greater than `number`, or None past `limit`."""
    candidate = number + 1
    while limit is None or candidate <= limit:
        if is_palindromic_number(candidate):
            return candidate
        candidate += 1
    return None


def palindromes_in_range(start, stop):
    """All palindromic numbers in the inclusive range [start, stop]."""
    found = []
    current = start - 1
    while True:
        current = next_palindrome(current, limit=stop)
        if current is None:
            break
        found.append(current)
    return found


def describe(text):
    """Turn one line of raw input into a human-readable verdict."""
    number = parse_number(text)
    if number is None:
        return "%r is not a valid integer" % (text,)
    verdict = "is" if is_palindromic_number(number) else "is not"
    following = next_palindrome(number, limit=number + 1000)
    tail = "" if following is None else " (next palindrome: %d)" % following
    return "%d %s palindromic%s" % (number, verdict, tail)


def main():
    samples = ["121", "123", " -7 ", "10", "", "12x", "9009"]
    for sample in samples:
        print(describe(sample))

    print("Palindromes between 100 and 200:", palindromes_in_range(100, 200))

    big = next_palindrome(98765, limit=99999)
    if big is not None:
        print("First palindrome above 98765:", big)


if __name__ == "__main__":
    main()

