import re
import sys

_READING = re.compile(r"([-+]?\d+(?:\.\d+)?)\s*(?:°\s*)?[cC]?$")


def celsius_to_fahrenheit(celsius):
    """Convert a Celsius temperature to Fahrenheit."""
    return celsius * 9 / 5 + 32


def parse_temperature(text):
    """Return the Celsius value written in `text`, or None if there is none."""
    match = _READING.match(text.strip())
    if match is None:
        return None
    return float(match.group(1))


def describe(celsius):
    """Short label for a Celsius reading, or None when it is unremarkable."""
    if celsius <= -273.15:
        return "below absolute zero"
    if celsius <= 0:
        return "freezing"
    if celsius >= 100:
        return "boiling"
    return None


def format_reading(celsius):
    """Build a one-line report for a single Celsius reading."""
    fahrenheit = celsius_to_fahrenheit(celsius)
    line = "{:.2f} C = {:.2f} F".format(celsius, fahrenheit)
    label = describe(celsius)
    if label is not None:
        line += " ({})".format(label)
    return line


def summarize(values):
    """Return the lowest and highest Celsius value, or None for each if empty."""
    lowest = None
    highest = None
    for value in values:
        if lowest is None or value < lowest:
            lowest = value
        if highest is None or value > highest:
            highest = value
    return lowest, highest


def report(texts):
    """Return the report lines, the parsed values and the unparsable inputs."""
    lines = []
    values = []
    failures = []
    for text in texts:
        celsius = parse_temperature(text)
        if celsius is None:
            failures.append(text)
            lines.append("{!r}: not a temperature".format(text))
        else:
            values.append(celsius)
            lines.append(format_reading(celsius))
    return lines, values, failures


def main(argv=None):
    if argv is None:
        argv = sys.argv
    readings = argv[1:]
    if not readings:
        readings = ["0", "100", "-40", "36.6C", "warm"]
    lines, values, failures = report(readings)
    for line in lines:
        print(line)
    lowest, highest = summarize(values)
    if lowest is not None:
        print("range: {:.2f} F to {:.2f} F".format(
            celsius_to_fahrenheit(lowest), celsius_to_fahrenheit(highest)))
    if failures:
        print("skipped {} bad reading(s)".format(len(failures)))
    return 1 if failures else 0


if __name__ == "__main__":
    sys.exit(main())

