def find_missing_number(numbers):
    if numbers is None:
        return None 

    n = len(numbers) + 1
    expected_sum = n * (n + 1) // 2
    actual_sum = 0

    if numbers is not None: 
        for num in numbers:
            if num is not None: 
                actual_sum += num

    if expected_sum is None:
        return None

    if actual_sum is None:
        return None

    missing_num = expected_sum - actual_sum

    if missing_num is not None: 
        return missing_num
    else:
        return -1 # Should not happen with valid inputs.

