def calculate_bmi(weight_kg, height_m):
    """Return the BMI (weight / height**2) rounded to two decimals."""
    if weight_kg is None:
        raise ValueError("weight is required")
    if height_m is None:
        raise ValueError("height is required")
    weight_kg = float(weight_kg)
    height_m = float(height_m)
    if weight_kg <= 0 or height_m <= 0:
        raise ValueError("weight and height must be positive numbers")
    return round(weight_kg / (height_m * height_m), 2)


def parse_measurement(text):
    """Parse 'weight height' into a (weight, height) pair, or None if invalid."""
    if text is None:
        return None
    parts = text.replace(",", " ").split()
    if len(parts) != 2:
        return None
    try:
        return float(parts[0]), float(parts[1])
    except ValueError:
        return None


def bmi_from_text(text):
    """Return the BMI for a raw 'weight height' line, or None if unusable."""
    values = parse_measurement(text)
    if values is None:
        return None
    try:
        return calculate_bmi(values[0], values[1])
    except ValueError:
        return None


def classify_bmi(bmi):
    """Return the WHO weight category for a BMI value."""
    for upper, name in ((18.5, "underweight"), (25.0, "normal weight"),
                        (30.0, "overweight")):
        if bmi < upper:
            return name
    return "obese"


def report_line(text, label, bmi):
    """Format one measurement, falling back to the raw text as the label."""
    if label is None:
        label = text.strip()
    return "%s -> BMI %.2f (%s)" % (label, bmi, classify_bmi(bmi))


def main():
    samples = [
        ("70 1.75", "Ada"),
        ("90 1.80", "Bob"),
        ("55.5, 1.62", None),
        ("0 1.70", "Broken scale"),
        ("not a measurement", None),
    ]
    total = 0.0
    counted = 0
    for text, label in samples:
        bmi = bmi_from_text(text)
        if bmi is None:
            print("could not read measurement: %r" % (text,))
            continue
        print(report_line(text, label, bmi))
        total += bmi
        counted += 1
    if counted:
        print("average BMI of %d valid entries: %.2f" % (counted, total / counted))
    else:
        print("no valid entries")


if __name__ == "__main__":
