    if compounding_frequency is None:
        raise ValueError("Compounding frequency cannot be None")
    if time_years is None:
        raise ValueError("Time in years cannot be None")

    if not isinstance(principal, (int, float)) or principal < 0:
        raise ValueError("Principal must be a non-negative number")
    if not isinstance(rate, (int, float)) or rate < 0:
        raise ValueError("Rate must be a non-negative number")
    if not isinstance(compounding_frequency, int) or compounding_frequency <= 0:
        raise ValueError("Compounding frequency must be a positive integer")
