def validate_2x2(matrix, name):
    """Return an error message, or None when `matrix` is a well-formed 2x2 matrix."""
    if matrix is None:
        return "%s is missing" % name
    if not isinstance(matrix, list) or len(matrix) != 2:
        return "%s must be a list of 2 rows" % name
    for index, row in enumerate(matrix):
        if not isinstance(row, list) or len(row) != 2:
            return "%s row %d must be a list of 2 numbers" % (name, index)
        for value in row:
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                return "%s row %d contains a non-numeric entry" % (name, index)
    return None


def multiply_2x2_matrices(matrix_a, matrix_b):
    error = validate_2x2(matrix_a, "matrix_a")
    if error is None:
        error = validate_2x2(matrix_b, "matrix_b")
    if error is not None:
        raise ValueError(error)
    result = [[0, 0], [0, 0]]
    for i in range(2):
        for j in range(2):
            result[i][j] = matrix_a[i][0] * matrix_b[0][j] + matrix_a[i][1] * matrix_b[1][j]
    return result


def multiply_chain(matrices):
    """Multiply a sequence of 2x2 matrices from left to right."""
    product = None
    for matrix in matrices:
        if product is None:
            error = validate_2x2(matrix, "matrix")
            if error is not None:
                raise ValueError(error)
            product = [list(matrix[0]), list(matrix[1])]
        else:
            product = multiply_2x2_matrices(product, matrix)
    if product is None:
        raise ValueError("at least one matrix is required")
    return product


def parse_matrix(text):
    """Parse "1 2; 3 4" into a 2x2 matrix, or return None if it is not parsable."""
    rows = [part.strip() for part in text.split(";")]
    if len(rows) != 2:
        return None
    matrix = []
    for row in rows:
        numbers = []
        for token in row.split():
            try:
                numbers.append(int(token))
            except ValueError:
                return None
        matrix.append(numbers)
    if validate_2x2(matrix, "matrix") is not None:
        return None
    return matrix


def format_matrix(matrix):
    width = max(len(str(value)) for row in matrix for value in row)
    lines = []
    for row in matrix:
        lines.append("[ " + "  ".join(str(value).rjust(width) for value in row) + " ]")
    return "\n".join(lines)


def main():
    pairs = [("1 2; 3 4", "5 6; 7 8"), ("1 0; 0 1", "10 20; 30 40"), ("2 0; 0 2", "bad input")]
    for left_text, right_text in pairs:
        operands = [parse_matrix(left_text), parse_matrix(right_text)]
        if any(matrix is None for matrix in operands):
            print("could not parse: %r x %r" % (left_text, right_text))
            continue
        print("%s x %s =" % (left_text, right_text))
        print(format_matrix(multiply_2x2_matrices(operands[0], operands[1])))
    print("chain of three:")
    print(format_matrix(multiply_chain([[[1, 2], [3, 4]], [[5, 6], [7, 8]], [[1, 0], [0, 1]]])))


if __name__ == "__main__":
    main()

