    if numbers is None or not numbers:
        return None

    counts = {}
    for num in numbers:
        if counts.get(num) is None:
            counts[num] = 0
        counts[num] += 1

    max_count = -1
    mode = None

    for num, count in counts.items():
        if mode is None:
