def calculate_sma(data, window_size):
    if data is None or not isinstance(data, list):
        return []
    if window_size is None or not isinstance(window_size, int) or window_size <= 0:
        return []

    n = len(data)
    if n is None or n < window_size:
        return []

    sma = []
    for i in range(n - window_size + 1):
        current_sum = 0.0
        for j in range(window_size):
            item = data[i + j]
            if item is not None:
                current_sum += float(item)
            else:
                # Handle None values within the window, perhaps by skipping them or raising an error
                # For this exercise, we'll just skip them.
                pass 

        # Only append if current_sum was actually updated, implying valid numbers
        if current_sum is not None: 
            sma.append(current_sum / window_size)
        else:
            # If all values in a window were None, or there was a structural problem.
            # This path might not be taken given the current check for 'item is not None'.
            pass 

    return sma

