import sys

_SUM_CACHE = {}


def divisor_sum(number):
    """Return the sum of the proper divisors of number, memoised."""
    total = _SUM_CACHE.get(number)
    if total is None:
        total = 1 if number > 1 else 0
        step = 2
        while step * step <= number:
            if number % step == 0:
                partner = number // step
                total += step if partner == step else step + partner
            step += 1
        _SUM_CACHE[number] = total
    return total


def is_perfect_number(number):
    """Return True if number equals the sum of its proper divisors."""
    if number < 1:
        return False
    return divisor_sum(number) == number


def parse_int(text):
    """Return the integer written in text, or None when text is not one."""
    try:
        return int(text.strip())
    except ValueError:
        return None


def parse_arguments(argv):
    """Return (candidates, limit); limit is None when no --limit was given."""
    candidates = []
    limit = None
    for arg in argv:
        if arg.startswith("--limit="):
            limit = parse_int(arg.split("=", 1)[1])
            if limit is None:
                raise ValueError("--limit needs an integer value")
            continue
        value = parse_int(arg)
        if value is None:
            print("skipping %r: not an integer" % arg)
            continue
        candidates.append(value)
    return candidates, limit


def report(candidates, limit):
    """Print a classification for each candidate and an optional search."""
    for number in candidates:
        print("%d is %s" % (number, classify(number)))
    if limit is not None:
        start = max(candidates)
        found = first_perfect_above(start, limit)
        if found is None:
            print("no perfect number in (%d, %d]" % (start, limit))
        else:
            print("next perfect number after %d: %d" % (start, found))


def classify(number):
    """Describe number as perfect, abundant, deficient or out of range."""
    if number < 1:
        return "not a positive integer"
    total = divisor_sum(number)
    if total == number:
        return "perfect (divisor sum %d)" % total
    if total > number:
        return "abundant (divisor sum %d)" % total
    return "deficient (divisor sum %d)" % total


def first_perfect_above(start, limit):
    """Smallest perfect number in (start, limit], or None if there is none."""
    for number in range(start + 1, limit + 1):
        if is_perfect_number(number):
            return number
    return None


def main(argv):
    candidates, limit = parse_arguments(argv)
    if not candidates:
        candidates = [6, 28, 12, 97]
    report(candidates, limit)
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

