_DIGITS = {'0': 0, '1': 1}


def digit_value(char):
    """Return the numeric value of a binary digit, or None if it is not one."""
    return _DIGITS.get(char)


def normalize_binary(text):
    """Strip decoration from a binary literal, or return None if unusable."""
    cleaned = text.strip().replace('_', '')
    if cleaned[:2].lower() == '0b':
        cleaned = cleaned[2:]
    if cleaned == '':
        return None
    return cleaned


def binary_to_decimal(binary_string):
    """Convert a binary string such as '1011' to the integer 11."""
    if not isinstance(binary_string, str):
        raise TypeError('binary_to_decimal expects a string')
    digits = normalize_binary(binary_string)
    if digits is None:
        raise ValueError('no binary digits found in %r' % (binary_string,))
    total = 0
    for char in digits:
        value = digit_value(char)
        if value is None:
            raise ValueError('invalid binary digit %r in %r' % (char, binary_string))
        total = total * 2 + value
    return total


def try_binary_to_decimal(binary_string):
    """Convert like binary_to_decimal, but return None instead of raising."""
    try:
        return binary_to_decimal(binary_string)
    except (TypeError, ValueError):
        return None


def convert_all(items, default=None):
    """Convert every item, substituting default for the ones that fail."""
    results = []
    for item in items:
        value = try_binary_to_decimal(item)
        if value is None:
            results.append(default)
        else:
            results.append(value)
    return results


def format_report(items, values):
    lines = []
    for item, value in zip(items, values):
        label = repr(item)
        if value is None:
            lines.append('%s -> invalid binary string' % label)
        else:
            lines.append('%s -> %d' % (label, value))
    return '\n'.join(lines)


def largest(values):
    """Return the biggest converted value, or None if none succeeded."""
    best = None
    for value in values:
        if value is None:
            continue
        if best is None or value > best:
            best = value
    return best


def main():
    samples = ['101', '1111', '1011', '0b1101', '1000_0001', '', '12', None]
    values = convert_all(samples)
    print(format_report(samples, values))
    widest = largest(values)
    if widest is None:
        print('no valid conversions')
    else:
        print('largest value: %d' % widest)


if __name__ == '__main__':
    main()

