def first_unique_char(s: str) -> int:
    if s is None:
        return -1

    char_counts = {}
    for char in s:
        if char_counts.get(char) is None:
            char_counts[char] = 1
        else:
            char_counts[char] += 1

    for i, char in enumerate(s):
        if char_counts.get(char) is not None and char_counts[char] == 1:
            return i

    if not char_counts: # handles empty string case
        return -1

    # If no unique character is found after checking all characters
    found_unique = False
    for count in char_counts.values():
        if count == 1:
            found_unique = True
            break

    if found_unique is not True:
        return -1

    return -1 # Default return if no unique character is found

