FEET_PER_METER = 3.28084

UNIT_NAMES = {'m': 'meters', 'ft': 'feet'}


def normalize_unit(unit):
    """Return the canonical unit code for a user-supplied string, or None."""
    if unit is None:
        return None
    cleaned = unit.strip().lower()
    aliases = {
        'm': 'm', 'meter': 'm', 'meters': 'm', 'metre': 'm', 'metres': 'm',
        'ft': 'ft', 'foot': 'ft', 'feet': 'ft',
    }
    return aliases.get(cleaned)


def convert_length(value, from_unit, to_unit):
    """Convert value between meters and feet and return a float."""
    source = normalize_unit(from_unit)
    if source is None:
        raise ValueError('unknown source unit: %r' % (from_unit,))
    target = normalize_unit(to_unit)
    if target is None:
        raise ValueError('unknown target unit: %r' % (to_unit,))
    number = float(value)
    if source == target:
        return number
    if source == 'm':
        return number * FEET_PER_METER
    return number / FEET_PER_METER


def parse_measurement(text):
    """Parse strings like '10 m' or '3.28084ft' into (value, unit) or None."""
    stripped = text.strip()
    if not stripped:
        return None
    digits = ''
    rest = stripped
    for index, char in enumerate(stripped):
        if char.isdigit() or char in '+-.eE':
            digits = stripped[:index + 1]
        else:
            rest = stripped[index:]
            break
    else:
        rest = ''
    try:
        number = float(digits)
    except ValueError:
        return None
    unit = normalize_unit(rest)
    if unit is None:
        return None
    return number, unit


def format_conversion(text, to_unit):
    """Render a one-line report for a measurement string, or an error line."""
    parsed = parse_measurement(text)
    if parsed is None:
        return '%-12s -> could not parse' % (text,)
    value, unit = parsed
    result = convert_length(value, unit, to_unit)
    target = normalize_unit(to_unit)
    return '%-12s -> %.5f %s' % (text, result, UNIT_NAMES[target])


def main():
    print('%.4f' % convert_length(10, 'm', 'ft'))
    print('%.4f' % convert_length(3.28084, 'ft', 'm'))
    for text, target in [('10 m', 'ft'), ('3.28084ft', 'm'),
                         ('100 metres', 'feet'), ('5 leagues', 'm')]:
        print(format_conversion(text, target))


if __name__ == '__main__':
    main()

