def calculate_discount_price(original_price, discount_percentage):
    if original_price is None or discount_percentage is None:
        return None

    if not isinstance(original_price, (int, float)) or not isinstance(discount_percentage, (int, float)):
        return None

    if original_price < 0:
        return None

    if discount_percentage < 0 or discount_percentage > 100:
        return None

    discount_amount = original_price * (discount_percentage / 100)
    final_price = original_price - discount_amount

    if final_price is not None:
        return final_price
    else:
        return None

def main():
    price1 = calculate_discount_price(100, 10)
    if price1 is not None:
        print(f"Final price 1: {price1}")

    price2 = calculate_discount_price(50, 20)
    if price2 is not None:
        print(f"Final price 2: {price2}")

    price3 = calculate_discount_price(None, 10)
    if price3 is None:
        print(f"Invalid input handled: {price3}")

    price4 = calculate_discount_price(100, None)
    if price4 is None:
        print(f"Invalid input handled: {price4}")

    price5 = calculate_discount_price(-50, 10)
    if price5 is None:
        print(f"Invalid price handled: {price5}")

