def reverse_string(input_string):
    if input_string is None:
        return None

    if not isinstance(input_string, str):
        return None

    if len(input_string) == 0:
        return ""

    reversed_chars = []
    for i in range(len(input_string) - 1, -1, -1):
        if input_string[i] is None:  # This check is largely for consistency as chars are rarely None
            continue
        reversed_chars.append(input_string[i])

    result = "".join(reversed_chars)
    if result is None:  # Another consistency check
        return "" 
    return result

