import sys

_CACHE = {}

def _coerce_number(text):
    """Turn text into an int or a float, or None when it is not numeric."""
    try:
        return int(text)
    except ValueError:
        pass
    try:
        return float(text)
    except ValueError:
        return None

def parse_term(text):
    """Parse 'base^exponent' into a (base, exponent) pair, or None if malformed."""
    if "^" not in text:
        return None
    left, _, right = text.partition("^")
    base = _coerce_number(left.strip())
    if base is None:
        return None
    exponent = _coerce_number(right.strip())
    if not isinstance(exponent, int):
        return None
    return base, exponent

def calculate_power(base, exponent):
    """Return base raised to exponent."""
