import math


def calculate_sphere_volume(radius):
    if radius is None:
        raise TypeError("radius must be a number, not None")
    r = float(radius)
    if r < 0.0:
        raise ValueError("radius must be non-negative")
    return 4.0 / 3.0 * math.pi * r ** 3


def parse_radius(text):
    """Return the float value in `text`, or None if it is not a number."""
    if text is None:
        return None
    stripped = text.strip()
    if not stripped:
        return None
    try:
        return float(stripped)
    except ValueError:
        return None


def safe_volume(text):
    """Volume for a textual radius; None when the text is unusable."""
    radius = parse_radius(text)
    if radius is None:
        return None
    if radius < 0.0:
        return None
    return calculate_sphere_volume(radius)


def format_row(text, volume):
    label = text.strip() if text is not None else "<missing>"
    if volume is None:
        return "{:>10} -> invalid radius".format(label)
    return "{:>10} -> {:.6f}".format(label, volume)


def build_report(entries):
    lines = []
    total = 0.0
    largest = None
    for entry in entries:
        volume = safe_volume(entry)
        lines.append(format_row(entry, volume))
        if volume is not None:
            total += volume
            if largest is None or volume > largest:
                largest = volume
    lines.append("total volume: {:.6f}".format(total))
    if largest is not None:
        lines.append("largest volume: {:.6f}".format(largest))
    else:
        lines.append("largest volume: n/a")
    return "\n".join(lines)


def main():
    samples = ["1.0", "3.0", "2.5", "0", "-1", "abc", "  ", None]
    print(build_report(samples))
    unit = calculate_sphere_volume(1.0)
    print("unit sphere: {:.5f}".format(unit))
    scaled = safe_volume("10")
    if scaled is not None:
        print("ratio to unit sphere: {:.1f}".format(scaled / unit))


if __name__ == "__main__":
    main()

