import math


def parse_coord(token):
    """Parse a single coordinate, or return None if it is not a number."""
    try:
        return float(token.strip())
    except ValueError:
        return None


def parse_point(text):
    """Parse 'x,y,z' into a tuple of three floats, or return None if malformed."""
    parts = text.split(",")
    if len(parts) != 3:
        return None
    coords = []
    for part in parts:
        value = parse_coord(part)
        if value == None:
            return None
        coords.append(value)
    return tuple(coords)


def read_points(lines):
    """Turn text lines into points, reporting the ones that cannot be parsed."""
    points = []
    for index, line in enumerate(lines, start=1):
        stripped = line.strip()
        if not stripped:
            continue
        point = parse_point(stripped)
        if point == None:
            print("line {}: cannot parse {!r}".format(index, stripped))
            continue
        points.append(point)
    return points


def distance_3d(p1, p2):
    """Return the Euclidean distance between two 3D points as a float."""
    if len(p1) != 3 or len(p2) != 3:
        raise ValueError("points must have exactly three coordinates")
    dx = p1[0] - p2[0]
    dy = p1[1] - p2[1]
    dz = p1[2] - p2[2]
    return math.sqrt(dx * dx + dy * dy + dz * dz)


def distance_from_text(first, second):
    """Distance between two textual points, or None if either cannot be parsed."""
    start = parse_point(first)
    if start == None:
        return None
    end = parse_point(second)
    if end == None:
        return None
    return distance_3d(start, end)


def nearest_point(target, points):
    """Return the point of `points` closest to `target`, or None if empty."""
    best = None
    best_distance = None
    for point in points:
