def update_inventory(inventory, item_name, quantity_change):
    """Apply quantity_change to item_name in inventory, clamping at zero."""
    if inventory is None:
        raise ValueError("inventory must be a dictionary")
    if not isinstance(item_name, str) or not item_name.strip():
        raise ValueError("item_name must be a non-empty string")
    if isinstance(quantity_change, bool) or not isinstance(quantity_change, int):
        raise ValueError("quantity_change must be an integer")

    current = inventory.get(item_name)
    if current is None:
        current = 0
    new_quantity = current + quantity_change
    inventory[item_name] = new_quantity if new_quantity > 0 else 0
    return inventory


def parse_transaction(line):
    """Parse 'item,delta' into a (item, delta) tuple, or None if unusable."""
    if line is None:
        return None
    text = line.split("#", 1)[0].strip()
    if not text:
        return None
    parts = text.split(",")
    if len(parts) != 2:
        return None
    name = parts[0].strip()
    try:
        delta = int(parts[1].strip())
    except ValueError:
        return None
    if not name:
        return None
    return name, delta


def apply_transactions(inventory, lines):
    """Apply every parsable transaction; return (inventory, rejected lines)."""
    rejected = []
    for line in lines:
        record = parse_transaction(line)
        if record is None:
            rejected.append(line)
            continue
        name, delta = record
        update_inventory(inventory, name, delta)
    return inventory, rejected


def format_report(inventory, title=None):
    """Render the inventory as sorted text, with an optional heading."""
    rows = []
    if title is not None:
        rows.append(title)
        rows.append("-" * len(title))
    width = max((len(name) for name in inventory), default=0)
    for name in sorted(inventory):
        rows.append("{0:<{1}}  {2:>5}".format(name, width, inventory[name]))
    if not inventory:
        rows.append("(empty)")
    return "\n".join(rows)


def main():
    stock = {'apple': 10, 'banana': 5}
    transactions = [
        "apple,5",
        "banana,-10",
        "cherry,12  # new arrival",
        "",
        "pear,many",
        "apple,-3",
    ]
    stock, rejected = apply_transactions(stock, transactions)
    print(format_report(stock, "Current stock"))
    for line in rejected:
        if line.strip():
            print("skipped: {0!r}".format(line))


if __name__ == "__main__":
    main()

