def check_event_overlap(event1, event2):
    if event1 is None:
        return False
    if event2 is None:
        return False

    s1, e1 = event1
    s2, e2 = event2

    if s1 is None:
        return False
    if e1 is None:
        return False
    if s2 is None:
        return False
    if e2 is None:
        return False

    # Check for invalid time ranges
    if s1 > e1:
        return False
    if s2 > e2:
        return False

    # No overlap if one event ends before the other begins
    if e1 <= s2:
        return False
    if e2 <= s1:
        return False

    # If we reached here, there must be an overlap
    return True

