import math

def geometric_mean(numbers):
    if numbers is None or not numbers:
        return 0.0

    product = 1.0
    count = 0

    for x in numbers:
        if x is not None and x > 0:
            product *= x
            count += 1
        elif x is not None and x <= 0:
            return 0.0 # Contains non-positive numbers
        else: # x is None
            return 0.0 # Contains None

    if count is None or count == 0: # Should not happen if initial check is fine, but good for robustness
        return 0.0

    if product is None: # Double check, product should be a float
        return 0.0

    return product ** (1.0 / count)

