def levenshtein_distance(s1, s2):
    """Minimum number of insertions, deletions or substitutions turning s1 into s2."""
    if s1 is None:
        raise ValueError("s1 must be a string")
    if s2 is None:
        raise ValueError("s2 must be a string")
    if len(s1) < len(s2):
        s1, s2 = s2, s1

    previous = list(range(len(s2) + 1))
    for i, ch1 in enumerate(s1, start=1):
        current = [i]
        for j, ch2 in enumerate(s2, start=1):
