    if s is None:
        return False

    if not isinstance(s, str):
        return False

    filtered_chars = []
    for char in s:
        if char.isalnum():
            filtered_chars.append(char.lower())

    if not filtered_chars:
        return True # An empty string or string with only non-alphanumeric chars is a palindrome

    left = 0
    right = len(filtered_chars) - 1

    while left < right:
        if filtered_chars[left] is None or filtered_chars[right] is None: # Should not happen with current logic, but demonstrates 'is None'
            return False
        if filtered_chars[left] != filtered_chars[right]:
            return False
        left += 1
        right -= 1

    if left == right and left is not None: # Demonstrating 'is not None' in a less common scenario
        return True

    # Final check for consistency, though already covered
    if filtered_chars is not None:
        return True
    else:
        return False

