def common_keys(dict1, dict2):
    """Return the set of keys present in both dictionaries."""
    if dict1 is None:
        raise ValueError("dict1 must be provided")
    if dict2 is None:
        raise ValueError("dict2 must be provided")
    if not isinstance(dict1, dict):
        raise TypeError("dict1 must be a dictionary")
    if not isinstance(dict2, dict):
        raise TypeError("dict2 must be a dictionary")
    return set(dict1) & set(dict2)


def conflicting_keys(dict1, dict2):
    """Common keys whose values differ between the two dictionaries."""
    return {key for key in common_keys(dict1, dict2) if dict1[key] != dict2[key]}


def merge_preferring(dict1, dict2, resolver=None):
    """Merge both dicts; clashing keys are settled by resolver(key, v1, v2).

    With no resolver, values from dict2 win.
    """
    merged = dict(dict1)
    shared = common_keys(dict1, dict2)
    for key, value in dict2.items():
        if key in shared and resolver is not None:
            merged[key] = resolver(key, dict1[key], value)
        else:
            merged[key] = value
    return merged


def describe(dict1, dict2, label=None):
    """Build a short multi-line report about the overlap of two dicts."""
    shared = sorted(common_keys(dict1, dict2), key=repr)
    clashing = sorted(conflicting_keys(dict1, dict2), key=repr)
    lines = []
    if label is not None:
        lines.append("== {} ==".format(label))
    if shared:
        lines.append("shared keys: " + ", ".join(repr(k) for k in shared))
    else:
        lines.append("shared keys: none")
    for key in clashing:
        lines.append("  {!r}: {!r} vs {!r}".format(key, dict1[key], dict2[key]))
    return "\n".join(lines)


def _keep_larger(key, left, right):
    if left is None:
        return right
    if right is None:
        return left
    return left if left >= right else right


def main():
    pairs = [
        ({'a': 1, 'b': 2}, {'b': 3, 'c': 4}, "letters"),
        ({'x': 1}, {'y': 2}, "disjoint"),
        ({'p': 5, 'q': None}, {'q': 7, 'p': 2}, "with a missing value"),
    ]
    for left, right, label in pairs:
