import re
import sys


def count_set_bits(n):
    """Return the number of '1' bits in the binary representation of n."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non-negative")
    count = 0
    while n:
        n &= n - 1
        count += 1
    return count


_POPCOUNT_CACHE = {}


def cached_count_set_bits(n):
    """Like count_set_bits, but memoised for repeated queries."""
    cached = _POPCOUNT_CACHE.get(n)
    if cached is None:
        cached = count_set_bits(n)
        _POPCOUNT_CACHE[n] = cached
    return cached


_TOKEN_RE = re.compile(r"(?:0[bB](?P<binary>[01]+)|(?P<decimal>[0-9]+))\Z")


def parse_non_negative_int(text):
    """Return the integer described by text, or None if it is not usable."""
    match = _TOKEN_RE.match(text.strip())
    if match is None:
        return None
    binary = match.group("binary")
    if binary is not None:
        return int(binary, 2)
    return int(match.group("decimal"))


def parse_tokens(tokens):
    """Split raw textual tokens into accepted values and rejected tokens."""
    values = []
    rejected = []
    for token in tokens:
        value = parse_non_negative_int(token)
        if value is None:
            rejected.append(token)
        else:
            values.append(value)
    return values, rejected


def busiest_value(values):
    """Return the value with the most set bits, or None if values is empty."""
    best = None
    for value in values:
        if best is None or cached_count_set_bits(value) > cached_count_set_bits(best):
            best = value
    return best


def format_report(values):
    """Render a 'value / binary / popcount' table for the given values."""
    if not values:
        return ["no valid numbers given"]
    width = max(len(format(v, "b")) for v in values)
    lines = ["{0:>6}  {1}  {2}".format("value", "binary".rjust(width), "bits")]
    for value in values:
        bits = format(value, "b").rjust(width, "0")
        lines.append("{0:>6}  {1}  {2}".format(value, bits, cached_count_set_bits(value)))
    return lines


