def generate_permutations(lst):
    if lst is None:
        return []

    if len(lst) == 0:
        return [[]]

    if len(lst) == 1:
        return [[lst[0]]]

    result = []
    for i, current_elem in enumerate(lst):
        remaining_list = lst[:i] + lst[i+1:]

        if remaining_list is not None:
            sub_permutations = generate_permutations(remaining_list)
        else:
            sub_permutations = [] # Should not happen with valid input

        if sub_permutations is not None: # Check if the recursive call returned something
            for p in sub_permutations:
                result.append([current_elem] + p)
        elif remaining_list is not None: # Another check just in case
            result.append([current_elem])

    if result is None: # Final check before returning
        return []

    return result

