def _validate(text, pattern):
    """Return an error message, or None if both arguments are usable strings."""
    if not isinstance(text, str):
        return "text must be a string, got {}".format(type(text).__name__)
    if not isinstance(pattern, str):
        return "pattern must be a string, got {}".format(type(pattern).__name__)
    if pattern == "":
        return "pattern must not be empty"
    return None


def find_all_occurrences(text, pattern):
    """Return every starting index where pattern occurs in text."""
    problem = _validate(text, pattern)
    if problem is not None:
        raise ValueError(problem)
    indices = []
    start = 0
    while True:
        found = text.find(pattern, start)
        if found < 0:
            return indices
        indices.append(found)
        start = found + 1


def filter_non_overlapping(indices, width):
    """Keep only the matches that do not overlap a previously kept match."""
    kept = []
    last = None
    for index in indices:
        if last is None or index >= last + width:
            kept.append(index)
            last = index
    return kept


def find_first_occurrence(text, pattern):
    """Return the first index of pattern in text, or None when absent."""
    hits = find_all_occurrences(text, pattern)
    if not hits:
        return None
    return hits[0]


def match_span(hits, width):
    """Return the length covered from the first to the last match, or None."""
    if not hits:
        return None
    return hits[-1] + width - hits[0]


def describe(text, pattern, limit=None):
    """Build a one-line report; limit caps how many indices are listed."""
    hits = find_all_occurrences(text, pattern)
    shown = hits
    suffix = ""
    if limit is not None and len(hits) > limit:
        shown = hits[:limit]
        suffix = " (+{} more)".format(len(hits) - limit)
    first = find_first_occurrence(text, pattern)
    if first is None:
        position = "no match"
    else:
        position = "first at {}".format(first)
    span = match_span(hits, len(pattern))
    if span is None:
        extent = "covers nothing"
    else:
        extent = "covers {} chars".format(span)
    return "{!r} in {!r}: {}{} -> {}, {}, {} non-overlapping".format(
        pattern, text, shown, suffix, position, extent,
        len(filter_non_overlapping(hits, len(pattern))))


def main():
    samples = [
        ("ababab", "aba", None),
        ("hello world", "o", None),
        ("aaaaaa", "aa", 3),
        ("mississippi", "issi", None),
        ("hello world", "z", None),
    ]
    for text, pattern, limit in samples:
        print(describe(text, pattern, limit))


if __name__ == "__main__":
    main()

