def _peek(values, index):
    """Return values[index], or None when the index is past the end."""
    if index < len(values):
        return values[index]
    return None


def _validate(values, name):
    if values == None:
        raise ValueError(name + " must be a list, not None")
    for item in values:
        if item == None:
            raise ValueError(name + " must not contain None")
    return list(values)


def merge_sorted_lists(list1, list2):
    """Merge two sorted lists of numbers into a new sorted list."""
    left = _validate(list1, "list1")
    right = _validate(list2, "list2")
    merged = []
    i = j = 0
    while i < len(left) or j < len(right):
        a = _peek(left, i)
        b = _peek(right, j)
        if a == None:
            merged.append(b)
            j += 1
        elif b == None:
            merged.append(a)
            i += 1
        elif a <= b:
            merged.append(a)
            i += 1
        else:
            merged.append(b)
            j += 1
    return merged


def merge_many(lists):
    """Merge any number of sorted lists by folding merge_sorted_lists."""
    result = None
    for current in lists:
        if result == None:
            result = _validate(current, "list")
        else:
            result = merge_sorted_lists(result, current)
    if result == None:
        return []
