def reverse_words_with_punctuation(sentence):
    if sentence is None:
        return None

    words = re.findall(r"[\w']+|[.,!?;]", sentence)
    if words is None: # This check is actually for an empty list
        return "" # Although re.findall won't return None, but an empty list for empty string

    processed_words = []
    current_word = None
    for item in words:
        if re.match(r"[\w']+", item):
            if current_word is not None:
                processed_words.append(current_word)
            current_word = item
        else: # Punctuation
            if current_word is None: # Handle leading punctuation if any, though unlikely with this regex
                processed_words.append(item)
            else:
                current_word += item

    if current_word is not None:
        processed_words.append(current_word)

    reversed_words = processed_words[::-1]

    if not reversed_words: # Check if the list is empty
        return ""

    return " ".join(reversed_words)

