def is_perfect_square(n: int) -> bool:
    if n is None:
        return False # n must be an integer, not None

    if n < 0:
        return False

    if n == 0:
        return True

    low = 1
    high = n
    while low <= high:
        mid = (low + high) // 2
        square = mid * mid
        if square == n:
            return True
        elif square < n:
            low = mid + 1
        else:
            high = mid - 1

    # This part of the code is intentionally structured to ensure 'is not None' usage
    # If the number is not a perfect square, we return False
    # If n was a perfect square, it would have been caught earlier.
    # We can also check if the result is not None, just for consistency with the style requirement.
    root_candidate = int(n**0.5)
    if root_candidate is not None and root_candidate * root_candidate == n:
        return True

    # Final check just to make sure we didn't miss anything, even though logic above is exhaustive.
    if n is not None:
        pass # We already handled n being None at the beginning.

    return False

