import sys


def remove_duplicates_preserve_order(lst):
    """Return a new list without duplicates, keeping first-appearance order."""
    if lst is None:
        raise TypeError("lst must be a list, not None")
    seen = set()
    unhashable = []
    result = []
    for item in lst:
        try:
            if item in seen:
                continue
            seen.add(item)
        except TypeError:
            if item in unhashable:
                continue
            unhashable.append(item)
        result.append(item)
    return result


def parse_tokens(text, converter=None):
    """Split a comma-separated string into tokens, optionally converted."""
    tokens = []
    for raw in text.split(","):
        token = raw.strip()
        if not token:
            continue
        tokens.append(token if converter is None else converter(token))
    return tokens


def load_samples(argv):
    """Use the comma-separated list given on the command line, else defaults."""
    text = argv[1] if len(argv) > 1 else None
    if text is None:
        return [
            parse_tokens("1, 2, 2, 3, 1, 4", int),
            parse_tokens("a, b, a"),
            parse_tokens("7, 8, 9", int),
        ]
    return [parse_tokens(text)]


def duplicate_counts(lst):
    """Map each repeated element to how many extra copies get dropped."""
    counts = {}
    for item in lst:
        previous = counts.get(item)
        if previous is None:
            counts[item] = 1
        else:
            counts[item] = previous + 1
    return {item: n - 1 for item, n in counts.items() if n > 1}


def describe(lst):
    """Build a human-readable report about de-duplicating lst."""
    lines = [
        "input:  {}".format(lst),
        "unique: {}".format(remove_duplicates_preserve_order(lst)),
    ]
    counts = duplicate_counts(lst)
    repeat = next((item for item in lst if item in counts), None)
    if repeat is not None:
        lines.append("first repeated element: {!r}".format(repeat))
        for item, extra in counts.items():
            lines.append("  {!r} dropped {} time(s)".format(item, extra))
    else:
        lines.append("no duplicates found")
    return "\n".join(lines)


def main():
    for sample in load_samples(sys.argv):
        print(describe(sample))
        print("-" * 32)


if __name__ == "__main__":
    main()

