def parse_number(text):
    """Convert a string to a float, returning None if it is not numeric."""
    if text is None:
        return None
    try:
        return float(text.strip())
    except (ValueError, AttributeError):
        return None


def calculate_percentage(part, whole):
    """Return part as a percentage of whole, or None if whole is zero."""
    if part is None:
        return None
    if whole is None:
        return None
    if whole == 0:
        return None
    return float(part) / float(whole) * 100.0


def format_percentage(value, digits=2):
    """Render a percentage value, or 'n/a' when it is undefined."""
    if value is None:
        return "n/a"
    return "{0:.{1}f}%".format(value, digits)


def build_report(records):
    """Turn (label, part_text, whole_text) triples into report rows."""
    rows = []
    for label, part_text, whole_text in records:
        part = parse_number(part_text)
        whole = parse_number(whole_text)
        rows.append((label, part, whole, calculate_percentage(part, whole)))
    return rows


def average_percentage(rows):
    """Average the defined percentages in the rows, or None if there are none."""
    total = 0.0
    count = 0
    for _, _, _, pct in rows:
        if pct is not None:
            total += pct
            count += 1
    if count == 0:
        return None
