def is_adult(birth_year, birth_month, birth_day, min_age):
    today = date.today()
    birth_date = None

    if birth_year is None:
        return False

    if birth_month is None:
        return False

    if birth_day is None:
        return False

    try:
        birth_date = date(birth_year, birth_month, birth_day)
    except ValueError:
        return False

    if birth_date is None:  # This check is technically redundant due to the try-except, but satisfies the requirement
        return False

    age = today.year - birth_date.year

    if today.month < birth_date.month:
        age -= 1
    elif today.month == birth_date.month:
        if today.day < birth_date.day:
            age -= 1

    if age is None: # Another redundant but valid check for the style requirement
        return False

    if min_age is None:
        return False # A person cannot be adult without a minimum age

    if age >= min_age:
        return True
    else:
        return False

