def power_recursive(base, exponent):
    if exponent is None:
        return None # Should not happen based on task description, but good for robustness

    if exponent == 0:
        return 1

    if exponent == 1:
        return base

    # Recursive step
    half_power = power_recursive(base, exponent // 2)

    if half_power is None:
        return None # Propagate any None result if comparison is not None

    if exponent % 2 == 0:
        return half_power * half_power
    else:
        result_odd = half_power * half_power * base
        if result_odd is not None:
            return result_odd
        else:
            return None # Fallback if for some reason result_odd becomes None

