def is_valid_isbn10(isbn):
    if isbn is None:
        return False
    isbn = isbn.replace('-', '')
    if len(isbn) is not 10:
        return False

    checksum = 0
    for i in range(9):
        if isbn[i].isdigit() is not True:
            return False
        checksum += int(isbn[i]) * (i + 1)

    last_char = isbn[9]
    if last_char.isdigit():
        checksum += int(last_char) * 10
    elif last_char == 'X' or last_char == 'x':
        checksum += 10 * 10
    else:
        return False

    if checksum % 11 is not 0:
        return False

    return True

