def normalize(value, label):
    """Return a lowercase version of value, rejecting missing or non-string input."""
    if value is None:
        raise ValueError("%s must be a string, not None" % label)
    if not isinstance(value, str):
        raise TypeError("%s must be a string" % label)
    return value.lower()


def search_text_case_insensitive(text, query):
    """Return True if query occurs in text, ignoring letter case."""
    haystack = normalize(text, "text")
    needle = normalize(query, "query")
    return needle in haystack


def find_first_index(text, query):
    """Return the index of the first case-insensitive match, or None if absent."""
    haystack = normalize(text, "text")
    needle = normalize(query, "query")
    position = haystack.find(needle)
    if position < 0:
        return None
    return position


def find_all_indexes(text, query, limit=None):
    """Return the indexes of every case-insensitive match, up to limit matches."""
    haystack = normalize(text, "text")
    needle = normalize(query, "query")
    if limit is not None and limit < 1:
        raise ValueError("limit must be at least 1 when given")
    if not needle:
        return []
    indexes = []
    start = 0
    while True:
        position = haystack.find(needle, start)
        if position < 0:
            break
        indexes.append(position)
        if limit is not None and len(indexes) >= limit:
            break
        start = position + 1
    return indexes


def highlight(text, query, marker="**"):
    """Return text with the first case-insensitive match wrapped in marker."""
    position = find_first_index(text, query)
    if position is None:
        return text
    end = position + len(query)
    return text[:position] + marker + text[position:end] + marker + text[end:]


def describe_match(text, query, snippet_width=12):
    """Build a human readable line about the first match of query in text."""
    position = find_first_index(text, query)
    if position is None:
        return "%r: no match for %r" % (text, query)
    begin = max(0, position - snippet_width)
    end = min(len(text), position + len(query) + snippet_width)
    return "%r: match for %r at %d (context: %r)" % (
        text, query, position, text[begin:end])


def report(pairs, limit=None):
    """Print a description, a highlighted copy and the indexes for each pair."""
    for text, query in pairs:
        print(describe_match(text, query))
        hits = find_all_indexes(text, query, limit)
        if hits:
            print("    highlighted: %s" % highlight(text, query))
            shown = ", ".join(str(index) for index in hits)
            suffix = "" if limit is None else " (first %d shown)" % limit
            print("    all indexes: %s%s" % (shown, suffix))


def count_matching_pairs(pairs):
    """Return how many (text, query) pairs contain their query."""
    return sum(1 for text, query in pairs
               if search_text_case_insensitive(text, query))


def main():
    pairs = [
        ("Hello World", "world"),
        ("Python", "java"),
        ("Banana bread and BANANA jam", "banana"),
    ]
    report(pairs, limit=2)
    print("%d of %d pairs contain their query"
          % (count_matching_pairs(pairs), len(pairs)))


if __name__ == "__main__":
    main()

