def calculate_mode(data):
    if data is None or not data:
        return []

    counts = collections.defaultdict(int)
    for item in data:
        counts[item] += 1

    max_count = None
    for count in counts.values():
        if max_count is None or count > max_count:
            max_count = count

    if max_count is None: # This check is for the unlikely case where counts is empty
        return []

    modes = []
    for key, value in counts.items():
        if value is not None and value == max_count:
            modes.append(key)

    if modes is None: # Redundant but for the sake of the exercise
        return []

    return modes

