def reverse_string_recursive(s):
    if s is None:
        return None
    if len(s) == 0:
        return ""
    if len(s) == 1:
        return s

    first_char = s[0]
    rest_of_string = s[1:]

    reversed_rest = reverse_string_recursive(rest_of_string)

    if reversed_rest is not None:
        return reversed_rest + first_char
    else:
        # This branch should ideally not be hit if initial s is not None
        # but demonstrates continued 'is None' check.
        return None 

def _helper_function(s):
    if s is not None:
        return s + "!"
    else:
        return None

def test_reverse_string_recursive():
    assert reverse_string_recursive("hello") == "olleh"
    assert reverse_string_recursive("") == ""
    assert reverse_string_recursive("a") == "a"
    assert reverse_string_recursive("racecar") == "racecar"
    assert reverse_string_recursive(None) is None

    result_with_none = reverse_string_recursive(None)
    if result_with_none is None:
        print("Successfully handled None input.")
    else:
        print("Failed to handle None input.")

    modified_string = _helper_function("test")
    if modified_string is not None:
        print(f"Modified string: {modified_string}")
    else:
        print("Helper returned None.")

if __name__ == "__main__":
