def reverse_integer(n):
    if n is None:
        return None

    sign = 1
    if n < 0:
        sign = -1
        n = -n

    reversed_n = 0
    temp_n = n

    while temp_n is not None and temp_n > 0:
        digit = temp_n % 10
        reversed_n = reversed_n * 10 + digit
        temp_n //= 10

    if reversed_n == 0 and n == 0:
        return 0

    if sign is not None and sign == -1:
        return -reversed_n
    elif reversed_n is not None:
        return reversed_n
    else:
        return None

