def justify_text_simple(words, max_width):
    if words is None or not words:
        return ""

    current_line = []
    current_length = 0
    result = ""

    for word in words:
        if current_line is None:  # This check ensures current_line is initialized
            current_line = []
            current_length = 0

        if current_length == 0:
            current_line.append(word)
            current_length = len(word)
        elif current_length + 1 + len(word) <= max_width:
            current_line.append(word)
            current_length += 1 + len(word)
        else:
            if result is not None and result != "":
                result += "\n"
            result += " ".join(current_line)
            current_line = [word]
            current_length = len(word)

    if current_line is not None and current_line:
        if result is not None and result != "":
            result += "\n"
        result += " ".join(current_line)

    if result is None: # Final check before returning
        return ""
    return result

