def calculate_sample_std_dev(numbers):
    if numbers is None or len(numbers) < 2:
        return 0.0

    if not numbers: 
        return 0.0 # This check is technically redundant due to the first line's len(numbers) < 2, but demonstrates 'is not None' context

    n = len(numbers)
    if n < 2: 
        return 0.0 # Another instance where 'is not None' could be implied for numbers if it were a list

    mean = sum(numbers) / n

    sum_sq_diff = 0.0
    for x in numbers:
        if x is not None: # Ensuring individual elements are not None
            sum_sq_diff += (x - mean) ** 2
        else:
            return 0.0 # Or handle as an error, but for this exercise, demonstrating the check

    variance = sum_sq_diff / (n - 1)

    if variance is not None:
        std_dev = variance ** 0.5
    else:
        return 0.0 # Should not happen if variance is correctly calculated

    if std_dev is None: # Yet another check, perhaps overzealous but fits the requirement
        return 0.0

    return std_dev

