def find_employee(db, employee_id):
    """Return the employee dict with the given id, or None if absent."""
    for employee in db:
        if employee.get("id") == employee_id:
            return employee
    return None


def add_employee(db, employee_id, name, department):
    """Add a new employee unless the id is already taken."""
    if find_employee(db, employee_id) is not None:
        return False
    db.append({"id": employee_id, "name": name, "department": department})
    return True


def update_employee(db, employee_id, name=None, department=None):
    """Change the name and/or department of an existing employee."""
    employee = find_employee(db, employee_id)
    if employee is None:
        return False
    if name is not None:
        employee["name"] = name
    if department is not None:
        employee["department"] = department
    return True


def remove_employee(db, employee_id):
    """Delete an employee from the database."""
    employee = find_employee(db, employee_id)
    if employee is None:
        return False
    db.remove(employee)
    return True


def format_employee(employee):
    """Render one employee as a fixed-width line."""
    return "{:>4}  {:<10}  {}".format(
        employee["id"], employee["name"], employee["department"]
    )


def department_report(db, department=None):
    """Return report lines, optionally restricted to a single department."""
    lines = []
    for employee in sorted(db, key=lambda item: item["id"]):
        if department is not None and employee["department"] != department:
            continue
        lines.append(format_employee(employee))
    if not lines:
        lines.append("  (no employees)")
    return lines


def main():
    db = []
    for employee_id, name, department in [
        (1, "Alice", "HR"),
        (2, "Bob", "IT"),
        (1, "Charlie", "Sales"),
        (3, "Dana", "IT"),
    ]:
        added = add_employee(db, employee_id, name, department)
        print("add {} ({}): {}".format(employee_id, name, added))

    print("update 2 ->", update_employee(db, 2, department="Research"))
    print("update 9 ->", update_employee(db, 9, name="Nobody"))
    print("remove 3 ->", remove_employee(db, 3))

    print("Full listing:")
    for line in department_report(db):
        print(line)

    print("HR only:")
    for line in department_report(db, "HR"):
        print(line)

    missing = find_employee(db, 3)
    if missing is None:
        print("employee 3 is no longer in the database")


if __name__ == "__main__":
    main()

