QUADRANT_NAMES = {
    0: "on an axis",
    1: "quadrant I",
    2: "quadrant II",
    3: "quadrant III",
    4: "quadrant IV",
}


def parse_number(text):
    """Convert a token to int or float, or return None if it is not numeric."""
    token = text.strip()
    if not token:
        return None
    try:
        return int(token)
    except ValueError:
        pass
    try:
        return float(token)
    except ValueError:
        return None


def parse_point(line):
    """Parse 'x, y' (or 'x y') into a tuple, or return None if malformed."""
    parts = line.replace(",", " ").split()
    if len(parts) != 2:
        return None
    x = parse_number(parts[0])
    if x is None:
        return None
    y = parse_number(parts[1])
    if y is None:
        return None
    return x, y


def get_quadrant(x, y):
    """Return the quadrant (1-4) containing (x, y), or 0 if it lies on an axis."""
    if x == 0 or y == 0:
        return 0
    if x > 0:
        return 1 if y > 0 else 4
    return 2 if y > 0 else 3


def tally_quadrants(lines):
    """Count how many parsed points fall in each quadrant, plus bad lines."""
    counts = dict.fromkeys(QUADRANT_NAMES, 0)
    unparsable = 0
    for line in lines:
        point = parse_point(line)
        if point is None:
            unparsable += 1
            continue
        counts[get_quadrant(*point)] += 1
    return counts, unparsable


def describe_point(line):
    """Return a human readable report for one input line, or None if unusable."""
    point = parse_point(line)
    if point is None:
        return None
    x, y = point
    quadrant = get_quadrant(x, y)
    return "({0}, {1}) -> {2} [{3}]".format(x, y, quadrant, QUADRANT_NAMES[quadrant])


def format_line_report(line):
    """Describe one line, falling back to a skip notice for bad input."""
    report = describe_point(line)
    if report is None:
        return "skipping unparsable input: {0!r}".format(line)
    return report


def main():
    samples = [
        "3, 5",
        "-2, 0",
        "-4 -7",
        "6.5, -1.25",
        "0 0",
        "two, three",
        "9",
    ]
    for line in samples:
        print(format_line_report(line))
    counts, unparsable = tally_quadrants(samples)
    print("--- summary ---")
    for quadrant in sorted(counts):
        print("{0}: {1}".format(QUADRANT_NAMES[quadrant], counts[quadrant]))
    print("unparsable lines: {0}".format(unparsable))


if __name__ == "__main__":
    main()

