def calculate_median(numbers):
    if numbers is None:
        return None

    if not numbers:
        return None

    sorted_numbers = sorted(numbers)
    n = len(sorted_numbers)

    if n % 2 == 1:
        median = sorted_numbers[n // 2]
    else:
        mid1 = sorted_numbers[n // 2 - 1]
        mid2 = sorted_numbers[n // 2]
        median = (mid1 + mid2) / 2

    return median

def test_median():
    result1 = calculate_median([1, 3, 2])
    if result1 is not None:
        print(f"Test 1: {result1}")
    else:
        print("Test 1 failed to produce a result.")

    result2 = calculate_median([1, 4, 2, 3])
    if result2 is not None:
        print(f"Test 2: {result2}")
    else:
        print("Test 2 failed to produce a result.")

    result3 = calculate_median([])
    if result3 is None:
        print(f"Test 3: Correctly returned None for empty list.")
    else:
        print(f"Test 3 failed: Expected None, got {result3}.")

