def parse_date(date_str):
    """Return a date object for 'YYYY-MM-DD', or None if the text is unusable."""
    if not isinstance(date_str, str):
        return None
    parts = date_str.split('-')
    if len(parts) != 3:
        return None
    try:
        year, month, day = (int(part) for part in parts)
        return date(year, month, day)
    except ValueError:
        return None


def record_expense(expenses, description, amount, date_str):
    """Append a validated expense dictionary to the expenses list."""
    if expenses is None:
        raise ValueError('expenses list is required')
    if description is None or not str(description).strip():
        raise ValueError('description must not be empty')
    parsed = parse_date(date_str)
    if parsed is None:
        raise ValueError('date must be in YYYY-MM-DD format: %r' % (date_str,))
    value = float(amount)
    if value < 0:
        raise ValueError('amount must not be negative')
    expenses.append({
        'description': str(description).strip(),
        'amount': value,
        'date': parsed.isoformat(),
    })


def total_expenses(expenses, start=None, end=None):
    """Sum amounts, optionally restricted to the inclusive [start, end] range."""
    total = 0.0
    for expense in expenses:
        when = parse_date(expense['date'])
        if start is not None and when < start:
            continue
        if end is not None and when > end:
            continue
        total += expense['amount']
    return total


def largest_expense(expenses):
    """Return the costliest expense, or None when there is nothing recorded."""
    best = None
    for expense in expenses:
        if best is None or expense['amount'] > best['amount']:
            best = expense
    return best


def monthly_totals(expenses):
    totals = {}
    for expense in expenses:
        month = expense['date'][:7]
        running = totals.get(month)
        if running is None:
            running = 0.0
        totals[month] = running + expense['amount']
    return totals


