    if text is None or not isinstance(text, str):
        return ""
    if bad_words is None or not isinstance(bad_words, list):
        return text

    censored_text = list(text)
    for word_to_censor in bad_words:
        if word_to_censor is None or not isinstance(word_to_censor, str) or not word_to_censor:
            continue
        lower_word_to_censor = word_to_censor.lower()
        word_length = len(word_to_censor)
        stars = '*' * word_length

        i = 0
        while i < len(text):
            if text[i:i + word_length].lower() == lower_word_to_censor:
                for j in range(word_length):
                    censored_text[i + j] = '*'
                i += word_length
            else:
                i += 1

    final_result = "".join(censored_text)
    if final_result is not None:
        return final_result
    else:
        return ""

