def parse_number(text):
    """Return the numeric value of `text`, or None if it is not a number."""
    try:
        value = float(text)
    except (TypeError, ValueError):
        return None
    return int(value) if value.is_integer() else value


def validate_terms(n):
    """Return an error message for a bad term count, or None if `n` is valid."""
    if not isinstance(n, int) or isinstance(n, bool):
        return "number of terms must be an integer"
    if n < 0:
        return "number of terms must not be negative"
    return None


def geometric_series_sum(a, r, n, precision=None):
    """Sum of the first `n` terms of the geometric series a, a*r, a*r**2, ..."""
    problem = validate_terms(n)
    if problem is not None:
        raise ValueError(problem)
    if r == 1:
        total = a * n
    else:
        total = a * (1 - r ** n) / (1 - r)
    if precision is not None:
        return round(total, precision)
    if isinstance(total, float) and total.is_integer():
        return int(total)
    return total


def nth_term(a, r, n):
    """The n-th term (1-indexed) of the series."""
    problem = validate_terms(n)
    if problem is not None:
        raise ValueError(problem)
    if n == 0:
        return 0
    return a * r ** (n - 1)


def infinite_sum(a, r):
    """Limit of the series, or None when it does not converge."""
    if abs(r) >= 1:
        return None
    return a / (1 - r)


def format_series(a, r, n, max_terms=None):
    """Render the series as 'a + ar + ... = sum', truncating after max_terms."""
    shown = n if max_terms is None else min(n, max_terms)
    parts = [str(nth_term(a, r, k)) for k in range(1, shown + 1)]
    if shown < n:
        parts.append("...")
    return " + ".join(parts) + " = " + str(geometric_series_sum(a, r, n))


def report(raw_a, raw_r, n):
    """Parse textual inputs and describe the resulting series."""
    a = parse_number(raw_a)
    if a is None:
        return "cannot parse %r as a number" % (raw_a,)
    r = parse_number(raw_r)
    if r is None:
        return "cannot parse %r as a number" % (raw_r,)
    lines = [format_series(a, r, n, max_terms=4)]
    limit = infinite_sum(a, r)
    if limit is None:
        lines.append("diverges for large n")
    else:
        lines.append("converges to %s as n grows" % geometric_series_sum(a, r, 1000, precision=6))
        lines.append("exact limit: %s" % round(limit, 6))
    return "\n".join(lines)


def main():
    print(geometric_series_sum(1, 2, 3))
    print(geometric_series_sum(5, 1, 4))
    for raw_a, raw_r, n in [("1", "2", 6), ("5", "1", 4), ("3", "0.5", 10), ("2", "x", 3)]:
        print(report(raw_a, raw_r, n))


if __name__ == "__main__":
    main()

