import sys


def _validate(main_string, sub_string):
    if not isinstance(main_string, str) or not isinstance(sub_string, str):
        raise TypeError("both arguments must be strings")


def next_occurrence(haystack_lower, needle_lower, start):
    """Return the index of the next case-insensitive match, or None."""
    if not needle_lower:
        return None
    found = haystack_lower.find(needle_lower, start)
    if found == -1:
        return None
    return found


def find_occurrence_positions(main_string, sub_string, limit=None):
    """Starting indices of sub_string in main_string, ignoring case.

    When limit is given, stop searching after that many matches.
    """
    _validate(main_string, sub_string)
    haystack = main_string.lower()
    needle = sub_string.lower()
    positions = []
    position = next_occurrence(haystack, needle, 0)
    while position is not None:
        positions.append(position)
        if limit is not None and len(positions) >= limit:
            break
        position = next_occurrence(haystack, needle, position + len(needle))
    return positions


def count_substring_occurrences_ci(main_string, sub_string):
    """Count case-insensitive occurrences of sub_string inside main_string."""
    return len(find_occurrence_positions(main_string, sub_string))


def first_occurrence_slice(main_string, sub_string):
    """Return the original-case text of the first match, or None if absent."""
    matches = find_occurrence_positions(main_string, sub_string, limit=1)
    if not matches:
        return None
    return main_string[matches[0]:matches[0] + len(sub_string)]


def describe(main_string, sub_string, label=None):
    """Build a one-line report about the matches found."""
    if label is None:
        label = repr(sub_string)
    sample = first_occurrence_slice(main_string, sub_string)
    if sample is None:
        return "{0}: 0 occurrences".format(label)
    positions = find_occurrence_positions(main_string, sub_string)
    joined = ", ".join(str(index) for index in positions)
    return "{0}: {1} occurrence(s) at [{2}], first written as {3!r}".format(
        label, len(positions), joined, sample)


def main(argv=None):
    if argv is None:
        argv = sys.argv[1:]
    if len(argv) >= 2:
        print(describe(argv[0], argv[1]))
        return 0
    if argv:
        print("usage: count_ci.py MAIN_STRING SUB_STRING")
        return 2
    samples = [
        ("Hello world, World wide web", "world", None),
        ("Python is Fun", "fun", "fun-check"),
        ("Nothing to see here", "xyz", "missing"),
    ]
    for text, pattern, label in samples:
        print(describe(text, pattern, label))
    return 0


if __name__ == "__main__":
    sys.exit(main())

