    if text is None:
        return None
    if not isinstance(shift, int):
        raise TypeError("Shift must be an integer.")

    result = []
    for char in text:
        if 'A' <= char <= 'Z':
            shifted_char = chr(((ord(char) - ord('A') + shift) % 26) + ord('A'))
            result.append(shifted_char)
        elif 'a' <= char <= 'z':
            shifted_char = chr(((ord(char) - ord('a') + shift) % 26) + ord('a'))
            result.append(shifted_char)
        else:
            result.append(char)

    final_result = "".join(result)
    if final_result is not None:
        return final_result
    else:
        return None # This branch is technically unreachable, but satisfies the requirement.

