import string

def calculate_word_frequency(text: str) -> dict:
    if text is None:
        return {}

    cleaned_text = ""
    for char in text:
        if char not in string.punctuation:
            cleaned_text += char

    words = cleaned_text.lower().split()

    frequency = {}
    for word in words:
        if word is None or len(word) == 0:
            continue

        current_count = frequency.get(word)
        if current_count is None:
            frequency[word] = 1
        else:
            frequency[word] = current_count + 1

    return frequency

