import re
import sys

_NUMBER = re.compile(r"[+-]?(?:\d+\.?\d*|\.\d+)")


def parse_side(text):
    """Return the side length encoded in *text*, or None if it is not a number."""
    match = _NUMBER.fullmatch(text.strip())
    if match is None:
        return None
    value = float(match.group())
    if value <= 0:
        return None
    return value


def parse_triangle_line(line):
    """Return (label, (s1, s2, s3)) for a 'label: a, b, c' line, or None."""
    if ":" in line:
        label, _, rest = line.partition(":")
    else:
        label, rest = "triangle", line
    sides = []
    for field in rest.replace(",", " ").split():
        value = parse_side(field)
        if value is None:
            return None
        sides.append(value)
    if len(sides) != 3:
        return None
    return label.strip(), tuple(sides)


def calculate_triangle_perimeter(side1, side2, side3):
    """Perimeter of the triangle with the three given side lengths."""
    return side1 + side2 + side3


def classify(side1, side2, side3, tolerance=None):
    """Name the triangle by how many of its sides are equal."""
    if tolerance is None:
        tolerance = 1e-9
    a, b, c = sorted((side1, side2, side3))
    if abs(c - a) <= tolerance:
        return "equilateral"
    if abs(b - a) <= tolerance or abs(c - b) <= tolerance:
        return "isosceles"
    return "scalene"


def is_valid(side1, side2, side3):
    a, b, c = sorted((side1, side2, side3))
    return a > 0 and a + b > c


def format_row(label, sides):
    perimeter = calculate_triangle_perimeter(*sides)
    kind = classify(*sides)
    return "{:<12} {:>10.4g}  {}".format(label, perimeter, kind)


def main(argv=None):
    if argv is None:
        argv = sys.argv[1:]
    if argv:
        lines = argv
    else:
        lines = sys.stdin.read().splitlines()
    largest = None
    for line in lines:
        if not line.strip():
            continue
        record = parse_triangle_line(line)
        if record is None:
            print("skipping unparsable input: {!r}".format(line.strip()))
            continue
        label, sides = record
        if not is_valid(*sides):
            print("skipping impossible triangle: {}".format(label))
            continue
        print(format_row(label, sides))
        perimeter = calculate_triangle_perimeter(*sides)
        if largest is None or perimeter > largest[1]:
            largest = (label, perimeter)
    if largest is not None:
        print("largest perimeter: {} ({:g})".format(largest[0], largest[1]))
    return 0


if __name__ == "__main__":
    sys.exit(main())

