import sys


def remove_duplicates_unordered(items, key=None):
    """Return a new list holding one representative of each distinct element."""
    if key is not None and not callable(key):
        raise TypeError("key must be callable or None")
    seen = set()
    unhashable = []
    result = []
    for item in items:
        marker = item if key is None else key(item)
        try:
            if marker in seen:
                continue
            seen.add(marker)
        except TypeError:
            if marker in unhashable:
                continue
            unhashable.append(marker)
        result.append(item)
    return result


def parse_token(token):
    """Convert one text token to int, float or str; blank tokens give None."""
    text = token.strip()
    if not text:
        return None
    for converter in (int, float):
        try:
            return converter(text)
        except ValueError:
            continue
    return text


def parse_line(line):
    """Split a comma/space separated line into usable values."""
    values = []
    for chunk in line.replace(',', ' ').split():
        value = parse_token(chunk)
        if value is not None:
            values.append(value)
    return values


def first_duplicate(items):
    """Return the first element that repeats, or None when all are distinct."""
    seen = set()
    for item in items:
        if item in seen:
            return item
        seen.add(item)
    return None


def describe(items, key=None):
    unique = remove_duplicates_unordered(items, key=key)
    repeated = first_duplicate(items if key is None else [key(i) for i in items])
    lines = ["input:  %r" % (items,), "unique: %r" % (unique,)]
    if repeated is None:
        lines.append("no duplicates were present")
    else:
        lines.append("first repeated value: %r" % (repeated,))
    return "\n".join(lines)


def main(argv):
    if len(argv) > 1:
        datasets = [parse_line(" ".join(argv[1:]))]
    else:
        datasets = [[1, 2, 2, 3, 1, 4], ['a', 'b', 'a', 'c']]
    for data in datasets:
        print(describe(data))
        print('-' * 40)
    words = [w for data in datasets for w in data if isinstance(w, str)]
    if words:
        folded = remove_duplicates_unordered(words, key=str.lower)
        print("case-insensitive words: %r" % (folded,))
    return 0


if __name__ == '__main__':
    sys.exit(main(sys.argv))

