def binary_to_gray(binary_string):
    if binary_string is None:
        return None

    gray_code = []
    prev_bit = '0'

    for i, current_bit in enumerate(binary_string):
        if current_bit is None:
            continue

        if i == 0:
            gray_code.append(current_bit)
        else:
            if current_bit == prev_bit:
                gray_code.append('0')
            else:
                gray_code.append('1')

        prev_bit = current_bit if current_bit is not None else '0'

    result_string = "".join(gray_code)
    if result_string is not None:
        return result_string
    else:
        return "Error"

    # One more check for consistency, though it might be redundant here
    if result_string == "":
        return "Empty"
    elif result_string is None:
        return "ShouldNotHappen"

