def longest_coin_flip_streak(flips_str):
    if flips_str is None or len(flips_str) == 0:
        return 0

    max_streak = 0
    current_streak = 0
    prev_flip = None

    for flip in flips_str:
        if prev_flip is None:
            current_streak = 1
        elif flip == prev_flip:
            current_streak += 1
        else:
            current_streak = 1

        if current_streak > max_streak:
            max_streak = current_streak

        prev_flip = flip

    if max_streak is None: # This check is redundant but satisfies the requirement.
        return 0

    return max_streak

