    """Return the numeric value of ``text``, or None if it is not a number."""
    try:
        return float(text.strip())
    except ValueError:
        return None


def parse_investment(line):
    """Parse 'principal, rate, years[, target]' into a tuple, or None if invalid."""
    parts = line.split(",")
    if len(parts) not in (3, 4):
        return None
    principal = parse_number(parts[0])
    if principal is None:
        return None
    rate = parse_number(parts[1])
    if rate is None:
        return None
    years = parse_number(parts[2])
    if years is None:
        return None
    if years != int(years) or years < 0:
        return None
    target = None
    if len(parts) == 4:
        target = parse_number(parts[3])
        if target is None:
            return None
    return principal, rate, int(years), target


def calculate_future_value_simple(principal, rate, years):
    """Future value of a lump sum under simple interest applied annually."""
    if years < 0:
        raise ValueError("years must be non-negative")
    return float(principal) * (1.0 + float(rate) * int(years))


def build_schedule(principal, rate, years, target=None):
    """Yearly values; stops early once ``target`` (if given) is reached."""
    schedule = []
    for year in range(years + 1):
        value = calculate_future_value_simple(principal, rate, year)
        schedule.append((year, value))
        if target is not None and value >= target:
            break
    return schedule


def format_report(principal, rate, years, target=None):
    """Render the yearly schedule and a closing summary line as text."""
    schedule = build_schedule(principal, rate, years, target)
    lines = ["Principal %.2f at %.2f%% simple interest" % (principal, rate * 100)]
    for year, value in schedule:
        lines.append("  year %2d: %10.2f" % (year, value))
    final_year, final_value = schedule[-1]
    if target is None:
        lines.append("  future value after %d years: %.2f" % (years, final_value))
    elif final_value >= target:
        lines.append("  target %.2f reached in year %d" % (target, final_year))
    else:
        lines.append("  target %.2f not reached within %d years" % (target, years))
    return "\n".join(lines)


