    raw_inputs = [
        "1000, 0.05, 1",
        "500, 0.1, 2",
        "2500, 0.04, 10, 3000",
        "1200, 0.03, 5, 5000",
        "800, x, 3",
    ]
    for line in raw_inputs:
        parsed = parse_investment(line)
        if parsed is None:
            print("Skipping malformed input: %r" % line)
            continue
        principal, rate, years, target = parsed
        print(format_report(principal, rate, years, target))


