import re
from collections import Counter

HASHTAG_PATTERN = re.compile(r"#([A-Za-z0-9]+)")


def extract_hashtags(text):
    """Return every hashtag in text, in order, without the leading '#'.

    A text of None is treated as an empty text, so callers may pass
    missing entries straight through.
    """
    if text is None:
        return []
    return HASHTAG_PATTERN.findall(text)


def first_hashtag(text):
    """The first hashtag of text, or None when text carries none."""
    if text is None:
        return None
    match = HASHTAG_PATTERN.search(text)
    if match is None:
        return None
    return match.group(1)


def leading_hashtags(texts):
    """The first hashtag of each text, skipping texts without one."""
    leads = []
    for text in texts:
        tag = first_hashtag(text)
        if tag is not None:
            leads.append(tag)
    return leads


def count_hashtags(texts):
    """Count how often each case-folded hashtag occurs across texts."""
    counts = Counter()
    for text in texts:
        counts.update(tag.lower() for tag in extract_hashtags(text))
    return counts


def most_common_hashtag(texts):
    """The most frequent case-folded hashtag, or None if there is none."""
    counts = count_hashtags(texts)
    if not counts:
        return None
    tag, _count = counts.most_common(1)[0]
    return tag


def format_report(texts):
    """One line per text, plus a summary of the most common hashtag."""
    counts = count_hashtags(texts)
    lines = []
    for index, text in enumerate(texts, start=1):
        if text is None:
            lines.append("%d: <missing text>" % index)
            continue
        tags = extract_hashtags(text)
        lines.append("%d: %s" % (index, ", ".join(tags) if tags else "(none)"))
    winner = most_common_hashtag(texts)
    if winner is None:
        lines.append("most common: none")
    else:
        lines.append("most common: %s (%d)" % (winner, counts[winner]))
    lines.append("leading: %s" % ", ".join(leading_hashtags(texts)))
    return "\n".join(lines)


def main():
    samples = ["This is a #test with #Python.", "No hashtags here!",
               "#python and #PYTHON and #Python3 are different tags", None]
    print(extract_hashtags(samples[0]))
    print(extract_hashtags(samples[1]))
    print(format_report(samples))


if __name__ == "__main__":
    main()

