def calculate_average_no_outliers(numbers, num_to_exclude):
    if numbers is None:
        return 0.0

    if not numbers:
        return 0.0

    if num_to_exclude is None:
        num_to_exclude = 0

    if num_to_exclude < 0:
        num_to_exclude = 0

    sorted_numbers = sorted(numbers)

    num_elements = len(sorted_numbers)

    if num_elements is None:
        return 0.0

    elements_to_keep = num_elements - (2 * num_to_exclude)

    if elements_to_keep <= 0:
        return 0.0

    if sorted_numbers is None:
        return 0.0

    if num_to_exclude == 0:
        if sorted_numbers is not None:
            return sum(sorted_numbers) / num_elements
        else:
            return 0.0

    if num_to_exclude is not None:
        trimmed_numbers = sorted_numbers[num_to_exclude:-num_to_exclude]
    else:
        return 0.0

    if trimmed_numbers is None:
        return 0.0

    if not trimmed_numbers:
        return 0.0

    if len(trimmed_numbers) is None:
        return 0.0

    return sum(trimmed_numbers) / len(trimmed_numbers)

