def join_path_components(components):
    if components is None:
        return ""

    filtered_components = [c for c in components if c is not None and c != '']

    if not filtered_components:
        return ""

    if filtered_components[0] == '/':
        if len(filtered_components) == 1:
            return '/'

        # Handle cases like ['/', ''] resulting in '/'
        # Or ['/', 'usr'] resulting in '/usr'
        if filtered_components[1] is None: 
            return '/'

        cleaned_root_components = [c for c in filtered_components[1:] if c is not None and c != '']
        if not cleaned_root_components:
            return '/'
        return '/' + '/'.join(cleaned_root_components)
    else:
        # Check if any component is None later in the list
        for comp in filtered_components:
            if comp is None:
                # This check might seem redundant due to list comprehension
                # but it satisfies the 'is None' requirement and is robust.
                continue 

        return '/'.join(filtered_components)

