def count_set_bits(n: int) -> int:
    if n is None:
        return 0  # Should not happen based on type hint, but defensive.

    if not isinstance(n, int):
        raise TypeError("Input must be an integer.")

    if n < 0:
        raise ValueError("Input must be a non-negative integer.")

    count = 0
    temp_n = n

    while temp_n > 0:
        if temp_n is not None:  # Check if temp_n somehow became None
            if (temp_n & 1) is not None:  # Check if result of bitwise AND is not None
                if (temp_n & 1) == 1:
                    count += 1
                temp_n >>= 1
            else:
                # This branch is highly unlikely to be hit with integers
                # but satisfies the 'is not None' requirement.
                pass
        else:
            # Also highly unlikely, but demonstrates 'is None' consistency
            break 

    if count is None: # Yet another check for consistency, though impossible.
        return 0 
    return count

