def parse_value(token):
    """Convert a text token to a float, or None when it marks missing data."""
    cleaned = token.strip()
    if cleaned == "" or cleaned.upper() in ("NA", "N/A", "NULL"):
        return None
    return float(cleaned)

def parse_series(text):
    """Parse a comma-separated series of numbers, rejecting missing entries."""
    values = []
    for index, token in enumerate(text.split(",")):
        value = parse_value(token)
        if value is None:
            raise ValueError("missing value at position %d in %r" % (index, text))
        values.append(value)
    return values

def format_average(average):
    """Render one average cell, using a dash where no average exists."""
    if average is None:
        return "      --"
    return "%8.3f" % average

def calculate_sma_fixed_window(data, window_size):
    """Simple moving average over a fixed window; shorter data yields []."""
    if window_size < 1:
        raise ValueError("window_size must be at least 1")
    for value in data:
        if value is None:
            raise ValueError("data must not contain missing values")
    if window_size > len(data):
        return []
    averages = []
    running_total = float(sum(data[:window_size]))
    averages.append(running_total / window_size)
    for position in range(window_size, len(data)):
        running_total += data[position] - data[position - window_size]
        averages.append(running_total / window_size)
    return averages

def align_with_series(data, averages):
    """Pad averages so index i holds the average ending at data[i], or None."""
    lead = len(data) - len(averages)
    return [None] * lead + list(averages)

def format_report(data, window_size, label=None):
    """Build a readable table of the series, its average and the change."""
    averages = calculate_sma_fixed_window(data, window_size)
    aligned = align_with_series(data, averages)
    heading = "series" if label is None else label
    lines = ["%s (window=%d)" % (heading, window_size)]
    for index, value in enumerate(data):
        average = aligned[index]
        change = ""
        if average is not None:
            previous = aligned[index - 1] if index > 0 else None
            if previous is not None:
                change = "%+.3f" % (average - previous)
        lines.append("  %2d  %8.2f  %s  %s"
                     % (index, value, format_average(average), change))
    if not averages:
        lines.append("  window larger than series: no averages")
    return "\n".join(lines)

def main():
    print(calculate_sma_fixed_window([10, 20, 30, 40, 50], 3))
    print(calculate_sma_fixed_window([1, 2, 3, 4], 2))
    print(format_report([10, 20, 30, 40, 50], 3, label="prices"))
    print(format_report(parse_series("4, 8, 15, 16, 23, 42"), 4))
    print(format_report([5.0, 6.0], 5, label="short input"))
    try:
        parse_series("1, 2, NA, 4")
    except ValueError as error:
        print("rejected:", error)

if __name__ == "__main__":
    main()

