def merge_dicts(d1, d2):
    """Merge two dictionaries; values from d2 win on conflicting keys."""
    if d1 is None:
        d1 = {}
    if d2 is None:
        d2 = {}
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise TypeError("merge_dicts expects dictionaries (or None)")
    merged = dict(d1)
    merged.update(d2)
    return merged


def deep_merge(d1, d2):
    """Recursively merge nested dictionaries, d2 taking precedence."""
    result = merge_dicts(d1, d2)
    for key, value in result.items():
        left = d1.get(key) if d1 is not None else None
        if isinstance(left, dict) and isinstance(value, dict):
            result[key] = deep_merge(left, value)
    return result


def merge_all(*dicts):
    """Fold any number of dictionaries together, later ones winning."""
    accumulated = None
    for current in dicts:
        if accumulated is None:
            accumulated = merge_dicts({}, current)
        else:
            accumulated = merge_dicts(accumulated, current)
    if accumulated is None:
        return {}
    return accumulated


def describe_conflicts(d1, d2):
    """Report keys present in both inputs and the value that was overridden."""
    conflicts = {}
    for key in d1:
        if key in d2 and d1[key] != d2[key]:
            conflicts[key] = (d1[key], d2[key])
    return conflicts


def format_config(config, prefix=""):
    """Render a (possibly nested) merged mapping as sorted key=value lines."""
    lines = []
    for key in sorted(config, key=str):
        value = config[key]
        label = "{}{}".format(prefix, key)
        if isinstance(value, dict):
            lines.extend(format_config(value, label + "."))
        elif value is None:
            lines.append("{} = <unset>".format(label))
        else:
            lines.append("{} = {!r}".format(label, value))
    return lines


def main():
    print(merge_dicts({'a': 1, 'b': 2}, {'b': 3, 'c': 4}))
    print(merge_dicts({'x': 10}, {'y': 20}))

    defaults = {'host': 'localhost', 'port': 8080, 'tls': {'enabled': False, 'cert': None}}
    user = {'port': 9090, 'tls': {'enabled': True}}
    env = {'host': 'example.com'}

    flat = merge_all(defaults, user, env)
    print(flat)

    settings = deep_merge(merge_dicts(defaults, {}), user)
    for line in format_config(deep_merge(settings, env)):
        print(line)

    for key, (old, new) in sorted(describe_conflicts(defaults, user).items()):
        print("overridden {}: {!r} -> {!r}".format(key, old, new))

    cert = settings['tls'].get('cert')
    if cert is None:
        print("warning: TLS enabled without a certificate path")


if __name__ == "__main__":
    main()

