PAIRS = {')': '(', ']': '[', '}': '{'}
OPENERS = frozenset(PAIRS.values())


def find_invalid_char(s):
    """Return the first character that is not a bracket, or None if all are."""
    for ch in s:
        if ch not in PAIRS and ch not in OPENERS:
            return ch
    return None


def is_balanced(s):
    """Return True if the bracket string s is properly nested and closed."""
    bad = find_invalid_char(s)
    if bad is not None:
        raise ValueError('not a bracket character: %r' % bad)
    stack = []
    for ch in s:
        if ch in OPENERS:
            stack.append(ch)
            continue
        top = stack.pop() if stack else None
        if top is None or top != PAIRS[ch]:
            return False
    return not stack


def first_error_position(s):
    """Return the index of the bracket that breaks the balance, or None."""
    stack = []
    for i, ch in enumerate(s):
        if ch in OPENERS:
            stack.append(i)
            continue
        expected = PAIRS.get(ch)
        if expected is None:
            return i
        if not stack or s[stack.pop()] != expected:
            return i
    if stack:
        return stack[0]
    return None


def describe(s):
    """Build a one-line human readable verdict for the string s."""
    bad = find_invalid_char(s)
    if bad is not None:
        return '%-12r invalid input (contains %r)' % (s, bad)
    pos = first_error_position(s)
    if pos is None:
        return '%-12r balanced' % (s,)
    return '%-12r unbalanced at index %d (%r)' % (s, pos, s[pos])


def main():
    samples = ['({[]})', '([)]', '', '(((', '){', '[{()}]', '(]']
    for sample in samples:
        print(describe(sample))
    broken = 'a(b)'
    try:
        is_balanced(broken)
    except ValueError as exc:
        print('%-12r rejected: %s' % (broken, exc))
    unbalanced = [s for s in samples if first_error_position(s) is not None]
    print('%d of %d samples are unbalanced' % (len(unbalanced), len(samples)))


if __name__ == '__main__':
    main()

