import sys

_CACHE = {}


def _coerce_count(value):
    """Return value as a non-negative int, or None if it cannot be read as one."""
    if value is None:
        return None
    if isinstance(value, bool):
        return None
    if isinstance(value, int):
        return value if value >= 0 else None
    if isinstance(value, str):
        text = value.strip()
        if not text.lstrip("+").isdigit():
            return None
        return int(text)
    return None


def fibonacci_sequence(n):
    """Return a list with the first n Fibonacci numbers, starting at 0."""
    count = _coerce_count(n)
    if count is None:
        raise ValueError("n must be a non-negative integer, got %r" % (n,))
    cached = _CACHE.get(count)
    if cached is not None:
        return list(cached)
    best_key = None
    for key in _CACHE:
        if key < count and (best_key is None or key > best_key):
            best_key = key
    if best_key is None:
        values = []
    else:
        values = list(_CACHE[best_key])
    while len(values) < count:
        if len(values) < 2:
            values.append(len(values))
        else:
            values.append(values[-1] + values[-2])
    _CACHE[count] = list(values)
    return values


def format_sequence(values, separator=None):
    """Render a sequence of numbers as text, comma separated by default."""
    if separator is None:
        separator = ", "
    return separator.join(str(v) for v in values)


def report(n, separator=None):
    """Build a one-line description of the first n Fibonacci numbers."""
    count = _coerce_count(n)
    if count is None:
        raise ValueError("n must be a non-negative integer, got %r" % (n,))
    values = fibonacci_sequence(count)
    if not values:
        return "fibonacci_sequence(%d) -> (empty)" % count
    body = format_sequence(values, separator)
    return "fibonacci_sequence(%d) -> [%s] (sum=%d)" % (count, body, sum(values))


def main(argv=None):
    if argv is None:
        argv = sys.argv[1:]
    requests = argv if argv else ["5", "1", "10"]
    status = 0
    for raw in requests:
        if _coerce_count(raw) is None:
            print("skipping %r: not a non-negative integer" % raw)
            status = 1
            continue
        print(report(raw))
    return status


if __name__ == "__main__":
    sys.exit(main())

