import sys


def trailing_zeros_factorial(n):
    """Return the number of trailing zeros in n! for a non-negative integer n."""
    if n < 0:
        raise ValueError("n must be non-negative")
    count = 0
    power = 5
    while power <= n:
        count += n // power
        power *= 5
    return count


def parse_non_negative_int(text):
    """Return text as a non-negative int, or None when it does not describe one."""
    stripped = text.strip()
    if not stripped.isdigit():
        return None
    return int(stripped)


def split_options(arguments):
    """Split command line arguments into input texts and an optional --target value."""
    texts = []
    target = None
    for item in arguments:
        if item.startswith("--target="):
            target = parse_non_negative_int(item.split("=", 1)[1])
            if target is None:
                raise ValueError("--target needs a non-negative integer")
        else:
            texts.append(item)
    return texts, target


def summarize(texts):
    """Return one report line per text plus the largest value that could be parsed."""
    lines = []
    largest = None
    for text in texts:
        value = parse_non_negative_int(text)
        if value is None:
            lines.append("{!r}: not a non-negative integer".format(text))
            continue
        zeros = trailing_zeros_factorial(value)
        lines.append("{}! ends in {} zero{}".format(value, zeros, "" if zeros == 1 else "s"))
        if largest is None or value > largest:
            largest = value
    return lines, largest


def report(texts, target):
    """Print the summary of the texts and, when asked, the answer for a target."""
    lines, largest = summarize(texts)
    for line in lines:
        print(line)
    if largest is not None:
        print("largest input {} reaches {} zeros".format(largest, trailing_zeros_factorial(largest)))
    if target is not None:
        print("smallest n with >= {} zeros: {}".format(target, first_with_at_least(target)))


def first_with_at_least(target):
    """Return the smallest n whose factorial has at least `target` trailing zeros."""
    low, high = 0, 5 * max(target, 1)
    while low < high:
        mid = (low + high) // 2
        if trailing_zeros_factorial(mid) >= target:
            high = mid
        else:
            low = mid + 1
    return low


if __name__ == "__main__":
    inputs, wanted = split_options(sys.argv[1:])
    report(inputs or ["5", "10", "25", "100"], wanted)

