import sys

_CACHE = {}


def parse_shift(token):
    """Return the integer shift encoded in ``token``, or None if it is not one."""
    try:
        return int(token)
    except ValueError:
        return None


def parse_request(line):
    """Turn a ``"<string> <shift>"`` line into a (string, shift) pair."""
    parts = line.split()
    if len(parts) != 2:
        return None
    shift = parse_shift(parts[1])
    if shift is None:
        return None
    return parts[0], shift


def rotate_string(s, n):
    """Rotate ``s`` by ``n`` positions, as in rotate_string('abcdef', 2) -> 'cdefab'."""
    if s is None:
        raise TypeError("cannot rotate None")
    if n is None:
        raise TypeError("shift must be an integer, not None")
    if not isinstance(s, str):
        raise TypeError("expected a string to rotate")
    length = len(s)
    if length == 0:
        return s
    offset = n % length
    key = (s, offset)
    cached = _CACHE.get(key)
    if cached is not None:
        return cached
    rotated = s[offset:] + s[:offset]
    _CACHE[key] = rotated
    return rotated


def rotate_many(lines):
    """Rotate every well-formed request; unparsable lines become None entries."""
    results = []
    for line in lines:
        request = parse_request(line)
        if request is None:
            results.append(None)
        else:
            text, shift = request
            results.append(rotate_string(text, shift))
    return results


def format_result(line, result):
    if result is None:
        return "%-20s -> could not parse request" % line
    return "%-20s -> %s" % (line, result)


def load_lines(argv):
    if len(argv) > 1:
        return argv[1:]
    text = sys.stdin.read().strip()
    if not text:
        return None
    return text.splitlines()


def main():
    lines = load_lines(sys.argv)
    if lines is None:
        sys.stderr.write("usage: rotate.py '<string> <shift>' ...\n")
        return 1
    for line, result in zip(lines, rotate_many(lines)):
        print(format_result(line.strip(), result))
    return 0


if __name__ == "__main__":
    sys.exit(main())

