    """Intersect a sequence of closed intervals; None if they share no point."""
    result = None
    for index, interval in enumerate(intervals):
        if index == 0:
            result = normalize_interval(interval)
        else:
            result = interval_intersection(result, interval)
        if result == None:
            return None
    return result


def format_interval(interval):
    """Render an interval (or the empty result) for display."""
    if interval == None:
        return "empty"
    start, end = interval
    if start == end:
        return "[{0}]".format(start)
    return "[{0}, {1}]".format(start, end)


def measure(interval):
    """Length of a closed interval, or None when there is nothing to measure."""
    if interval == None:
        return None
    return interval[1] - interval[0]


def main():
    pairs = [
        ((1, 5), (3, 7)),
        ((1, 2), (3, 4)),
        ((0, 10), (10, 20)),
        ((8, 3), (4, 6)),
        ((1, 4), None),
    ]
    for left, right in pairs:
        overlap = interval_intersection(left, right)
        size = measure(overlap)
        line = "{0} & {1} -> {2}".format(left, right, format_interval(overlap))
        if size != None:
            line += " (length {0})".format(size)
        print(line)

    chain = [(0, 100), (10, 60), (25, 40), (30, 35)]
    common = intersect_all(chain)
    print("common of {0}: {1}".format(chain, format_interval(common)))
    if common != None:
        print("midpoint: {0}".format((common[0] + common[1]) / 2))


if __name__ == "__main__":
    main()

