class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

    def __repr__(self):
        return "ListNode({})".format(self.val)


def build_list(values):
    head = None
    tail = None
    for value in values:
        node = ListNode(value)
        if head is None:
            head = node
        else:
            tail.next = node
        tail = node
    return head


def to_list(head):
    values = []
    node = head
    while node is not None:
        values.append(node.val)
        node = node.next
    return values


def format_list(head):
    values = to_list(head)
    if not values:
        return "None"
    return "->".join(str(v) for v in values)


def length(head):
    count = 0
    node = head
    while node is not None:
        count += 1
        node = node.next
    return count


def remove_nth_from_end(head, n):
    if head is None:
        return None
    if n < 1 or n > length(head):
        raise ValueError("n must be between 1 and the length of the list")

    sentinel = ListNode(0, head)
    lead = sentinel
    for _ in range(n):
        lead = lead.next

    trail = sentinel
    while lead.next is not None:
        lead = lead.next
        trail = trail.next

    trail.next = trail.next.next
    return sentinel.next


def main():
    cases = [([1, 2, 3, 4, 5], 2), ([1], 1), ([7, 8], 2), ([], 1)]
    for values, n in cases:
        head = build_list(values)
        before = format_list(head)
        try:
            result = remove_nth_from_end(head, n)
        except ValueError as err:
            print("{} (n={}) -> error: {}".format(before, n, err))
            continue
        if result is None:
            print("{} (n={}) -> None".format(before, n))
        else:
            print("{} (n={}) -> {}".format(before, n, format_list(result)))


if __name__ == "__main__":
