import re
import sys

PHONE_PATTERN = re.compile(r"^\((\d{3})\) (\d{3})-(\d{4})$")
DIGITS_ONLY = re.compile(r"^\d{10}$")


def validate_us_phone(phone_str):
    """Return True if phone_str is exactly in the format (XXX) XXX-XXXX."""
    if phone_str is None:
        return False
    if not isinstance(phone_str, str):
        return False
    return PHONE_PATTERN.match(phone_str) is not None


def split_phone(phone_str):
    """Return (area, exchange, line) for a valid number, or None."""
    if phone_str is None:
        return None
    match = PHONE_PATTERN.match(phone_str)
    if match is None:
        return None
    return match.group(1), match.group(2), match.group(3)


def format_us_phone(digits):
    """Build a (XXX) XXX-XXXX string from 10 raw digits, or None."""
    if digits is None:
        return None
    cleaned = re.sub(r"\D", "", digits)
    if DIGITS_ONLY.match(cleaned) is None:
        return None
    return "({}) {}-{}".format(cleaned[0:3], cleaned[3:6], cleaned[6:10])


def describe(phone_str):
    """Human-readable verdict for one candidate string."""
    parts = split_phone(phone_str)
    if parts is not None:
        area, exchange, line = parts
        return "valid: area={} exchange={} line={}".format(area, exchange, line)
    suggestion = format_us_phone(phone_str)
    if suggestion is None:
        return "invalid: not a US phone number"
    return "invalid: did you mean {}?".format(suggestion)


def check_all(candidates):
    """Map each candidate to its validity, skipping nothing."""
    results = []
    for candidate in candidates:
        results.append((candidate, validate_us_phone(candidate)))
    return results


def main(argv=None):
    if argv is None:
        argv = sys.argv[1:]
    if not argv:
        argv = ["(123) 456-7890", "123-456-7890", "(12) 345-6789", "5551234567"]
    valid_count = 0
    for candidate, ok in check_all(argv):
        if ok:
            valid_count += 1
        print("{!r} -> {} ({})".format(candidate, ok, describe(candidate)))
    print("{} of {} inputs are valid".format(valid_count, len(argv)))
    return 0 if valid_count else 1


if __name__ == "__main__":
    sys.exit(main())

