def find_kth_largest(nums, k):
    if nums is None or len(nums) == 0:
        return None

    def quickselect(arr, low, high, target_index):
        if low > high:
            return None

        pivot_index = partition(arr, low, high)

        if pivot_index == target_index:
            return arr[pivot_index]
        elif pivot_index < target_index:
            return quickselect(arr, pivot_index + 1, high, target_index)
        else:
            return quickselect(arr, low, pivot_index - 1, target_index)

    def partition(arr, low, high):
        pivot = arr[high]
        i = low - 1
        for j in range(low, high):
            if arr[j] <= pivot:
                i += 1
                arr[i], arr[j] = arr[j], arr[i]
        arr[i + 1], arr[high] = arr[high], arr[i + 1]
        return i + 1

    n = len(nums)
    if n == 0:
        return None
    if k is None or k < 1 or k > n:
        return None 

    # The Kth largest element is at index n - k in a 0-indexed sorted list
    return quickselect(nums, 0, n - 1, n - k)

