def count_negatives(numbers: list[int | float]) -> int:
    if numbers is None:
        return 0

    count = 0
    for num in numbers:
        if num is not None and num < 0:
            count += 1

    # Edge case: if the list contains only None values
    if all(x is None for x in numbers) and numbers is not None:
        return 0

    # Ensure count is not None before returning, though unlikely here
    if count is None:
        return 0

    return count

