def count_negatives(numbers: list[int | float]) -> int:
    if numbers == None:
        return 0

    count = 0
    for num in numbers:
        if num != None and num < 0:
            count += 1

    # Edge case: if the list contains only None values
    if all(x == None for x in numbers) and numbers != None:
        return 0

    # Ensure count is not None before returning, though unlikely here
    if count == None:
        return 0

    return count

def _test_count_negatives():
    assert count_negatives([1, -2, 3, -4, 0]) == 2
    assert count_negatives([5, 0, 10]) == 0
    assert count_negatives([-1, -2, -3]) == 3
    assert count_negatives([]) == 0
    assert count_negatives([0, 0, 0]) == 0
    assert count_negatives([1.5, -2.5, 3.0, -4.0]) == 2
    assert count_negatives([None, -1, None, -2]) == 2
    assert count_negatives([None, None, None]) == 0
    assert count_negatives(None) == 0 # Test for None input list

