def first_inversion_index(numbers: list[int | float]) -> int | None:
    """Return the index of the first element smaller than its predecessor, or None."""
    previous = None
    for index, value in enumerate(numbers):
        if previous is not None and value < previous:
            return index
        previous = value
    return None


def is_sorted_ascending(numbers: list[int | float]) -> bool:
    """Return True when the numbers are in non-decreasing order."""
    return first_inversion_index(numbers) is None


def parse_number(token: str) -> int | float | None:
    """Convert a token to an int or float, or None when it is not numeric."""
    token = token.strip()
    try:
        return int(token)
    except ValueError:
        pass
    try:
        return float(token)
    except ValueError:
        return None


def parse_numbers(text: str) -> list[int | float]:
    """Parse a comma or whitespace separated list of numbers, rejecting bad tokens."""
    values: list[int | float] = []
    for token in text.replace(",", " ").split():
        value = parse_number(token)
        if value is None:
            raise ValueError(f"not a number: {token!r}")
        values.append(value)
    return values


def value_range(numbers: list[int | float]) -> tuple[int | float, int | float] | None:
    """Return the smallest and largest values, or None for an empty list."""
    low = None
    high = None
    for value in numbers:
        if low is None or value < low:
            low = value
        if high is None or value > high:
            high = value
    if low is None:
        return None
    return low, high


def describe(numbers: list[int | float]) -> str:
    """Build a human readable verdict for one list of numbers."""
    shown = "[" + ", ".join(str(value) for value in numbers) + "]"
    extent = value_range(numbers)
    if extent is None:
        return f"{shown} -> True (an empty list is sorted)"
    position = first_inversion_index(numbers)
    if position is None:
        return f"{shown} -> True (sorted from {extent[0]} to {extent[1]})"
    return f"{shown} -> False ({numbers[position]} at index {position} breaks the order)"


def main() -> None:
    samples = ["1, 2, 3, 4, 5", "1, 3, 2", "", "7", "-4 -4 0 2.5 10", "3 1 abc"]
    for sample in samples:
        try:
            numbers = parse_numbers(sample)
        except ValueError as error:
            print(f"{sample!r} -> input error: {error}")
            continue
        print(describe(numbers))


if __name__ == "__main__":
    main()

