"""Generation and reporting utilities for the Fibonacci sequence."""

import sys

_CACHE: dict[int, list[int]] = {}


def generate_fibonacci(n: int) -> list[int]:
    """Return the first ``n`` terms of the Fibonacci sequence."""
    if n < 0:
        raise ValueError("n must be non-negative")
    cached = _CACHE.get(n)
    if cached is not None:
        return list(cached)
    terms: list[int] = []
    current, following = 0, 1
    while len(terms) < n:
        terms.append(current)
        current, following = following, current + following
    _CACHE[n] = list(terms)
    return terms


def parse_count(text: str | None) -> int | None:
    """Turn a command line argument into a term count, or ``None`` if unusable."""
    if text is None:
        return None
    stripped = text.strip()
    if not stripped.isdigit():
        return None
    return int(stripped)


def find_index(value: int, terms: list[int]) -> int | None:
    """Return the position of ``value`` among ``terms``, or ``None`` if absent."""
    for index, term in enumerate(terms):
        if term == value:
            return index
    return None


def format_sequence(terms: list[int], limit: int | None = None) -> str:
    """Render ``terms`` as a comma separated string, optionally truncated."""
    shown = terms
    if limit is not None and limit < len(terms):
        shown = terms[:limit]
        return ", ".join(str(term) for term in shown) + ", ..."
    return ", ".join(str(term) for term in shown)


def describe(n: int, probe: int | None = None) -> str:
    """Build a one-paragraph report about the first ``n`` Fibonacci terms."""
    terms = generate_fibonacci(n)
    lines = [f"first {n} term(s): [{format_sequence(terms, limit=12)}]"]
    if terms:
        lines.append(f"largest term: {terms[-1]}")
        lines.append(f"sum of terms: {sum(terms)}")
    if probe is not None:
        position = find_index(probe, terms)
        if position is None:
            lines.append(f"{probe} does not occur in these terms")
        else:
            lines.append(f"{probe} occurs at index {position}")
    return "\n".join(lines)


def main(argv: list[str]) -> int:
    raw_count = argv[1] if len(argv) > 1 else None
    count = parse_count(raw_count)
    if count is None:
        if raw_count is not None:
            print(f"ignoring invalid term count {raw_count!r}", file=sys.stderr)
        count = 10
    probe = parse_count(argv[2]) if len(argv) > 2 else None
    print(describe(count, probe))
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv))

