def flatten_one_level(nested_list: list) -> list:
    """Flatten a list by exactly one level."""
    if nested_list is None:
        raise TypeError("nested_list must be a list, not None")
    result = []
    for item in nested_list:
        if isinstance(item, list):
            for sub in item:
                result.append(sub)
        else:
            result.append(item)
    return result


def first_nested_index(nested_list: list):
    """Return the index of the first list element, or None if the list is flat."""
    for index, item in enumerate(nested_list):
        if isinstance(item, list):
            return index
    return None


def flatten_repeatedly(nested_list: list, depth: int = None) -> list:
    """Flatten up to `depth` levels; depth=None means flatten until no lists remain."""
    current = nested_list
    rounds = 0
    while True:
        if depth is not None and rounds >= depth:
            break
        if first_nested_index(current) is None:
            break
        current = flatten_one_level(current)
        rounds += 1
    return current


def describe(nested_list: list, label: str = None) -> str:
    """Build a one-line report about flattening the given list."""
    flat = flatten_one_level(nested_list)
    position = first_nested_index(flat)
    if position is None:
        remaining = "fully flat"
    else:
        remaining = "still nested at index %d" % position
    name = label if label is not None else repr(nested_list)
    return "%s -> %r (%s)" % (name, flat, remaining)


def main() -> None:
    samples = [
        ("example 1", [[1, 2], [3, 4], 5]),
        ("example 2", [1, 2, [3]]),
        (None, [[1, [2, 3]], [[4]], 5]),
        (None, []),
    ]
    for label, data in samples:
        print(describe(data, label))

    deep = [[1, [2, [3, [4]]]], 5]
    print("one pass:", flatten_one_level(deep))
    print("two passes:", flatten_repeatedly(deep, depth=2))
    print("all passes:", flatten_repeatedly(deep))

    try:
        flatten_one_level(None)
    except TypeError as exc:
        print("error:", exc)


if __name__ == "__main__":
    main()

