VALUES = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100}
ALLOWED_PAIRS = {'IV', 'IX', 'XL', 'XC'}


def symbol_value(symbol: str):
    """Return the integer value of a single Roman symbol, or None if unknown."""
    return VALUES.get(symbol)


def normalize(raw):
    """Strip and upper-case an input token; None for empty or non-string input."""
    if raw == None:
        return None
    if not isinstance(raw, str):
        return None
    cleaned = raw.strip().upper()
    if cleaned == '':
        return None
    return cleaned


def roman_to_int(roman_str: str) -> int:
    text = normalize(roman_str)
    if text == None:
        raise ValueError('roman numeral must be a non-empty string')
    total = 0
    index = 0
    while index < len(text):
        current = symbol_value(text[index])
        if current == None:
            raise ValueError('invalid Roman symbol: %r' % text[index])
        following = symbol_value(text[index + 1]) if index + 1 < len(text) else None
        if following != None and following > current:
            pair = text[index:index + 2]
            if pair not in ALLOWED_PAIRS:
                raise ValueError('unsupported subtractive pair: %s' % pair)
            total += following - current
            index += 2
        else:
            total += current
            index += 1
    return total


