def find_item(inventory: dict[str, int], item: str) -> str | None:
    """Return the stored key matching item ignoring case, else None."""
    if item in inventory:
        return item
    wanted = item.strip().lower()
    for key in inventory:
        if key.lower() == wanted:
            return key
    return None


def quantity_of(inventory: dict[str, int], item: str) -> int | None:
    """Return the stock held for item, or None when it is unknown."""
    key = find_item(inventory, item)
    if key is None:
        return None
    return inventory[key]


def update_inventory(inventory: dict[str, int], item: str, quantity_change: int) -> dict[str, int]:
    """Add or remove stock for one item, never dropping below zero."""
    if not item.strip():
        raise ValueError("item name must be a non-empty string")
    key = find_item(inventory, item)
    if key is None:
        key = item
    new_amount = inventory.get(key, 0) + quantity_change
    inventory[key] = new_amount if new_amount > 0 else 0
    return inventory


def parse_command(line: str) -> tuple[str, int] | None:
    """Parse "name <+/-amount>" into (name, change); None if unusable."""
    text = line.strip()
    if not text or text.startswith("#"):
        return None
    parts = text.rsplit(None, 1)
    if len(parts) != 2:
        return None
    name, raw = parts
    try:
        change = int(raw)
    except ValueError:
        return None
    return name, change


def apply_commands(inventory: dict[str, int], lines: list[str]) -> list[str]:
    """Run every command line, returning messages about doubtful ones."""
    problems: list[str] = []
    for number, line in enumerate(lines, start=1):
        command = parse_command(line)
        if command is None:
            problems.append(f"line {number}: cannot read {line.strip()!r}")
            continue
        name, change = command
        held = quantity_of(inventory, name)
        if held is None and change < 0:
            problems.append(f"line {number}: {name!r} was not in stock, set to 0")
        update_inventory(inventory, name, change)
    return problems


def format_report(inventory: dict[str, int], title: str | None = None) -> str:
    """Render the inventory as aligned rows, optionally under a title."""
    rows = []
    if title is not None:
        rows.append(title)
    for key in sorted(inventory):
        rows.append(f"{key:<10} {inventory[key]:>4}")
    return "\n".join(rows)


def main() -> None:
    stock = {"apple": 10, "banana": 5}
    script = [
        "apple 2",
        "banana -8",
        "# restock",
        "Cherry 12",
        "pear -3",
        "plum many",
    ]
    for message in apply_commands(stock, script):
        print("warning:", message)
    print(format_report(stock, title="Inventory"))


if __name__ == "__main__":
    main()

