import sys
from typing import List, Optional


def parse_dimension(text: str) -> Optional[int]:
    """Convert a command line token into a positive integer, or None if it is not one."""
    try:
        value = int(text)
    except ValueError:
        return None
    if value < 1:
        return None
    return value


def validate_dimensions(width: int, height: int) -> Optional[str]:
    """Return a description of the problem with the dimensions, or None when they are fine."""
    for name, value in (("width", width), ("height", height)):
        if not isinstance(value, int) or isinstance(value, bool):
            return f"{name} must be an integer, got {type(value).__name__}"
        if value < 1:
            return f"{name} must be at least 1, got {value}"
    return None


def build_row(width: int, fill: Optional[str] = None) -> str:
    """Build a single row of the rectangle, using '*' unless another fill is given."""
    if fill is None:
        fill = "*"
    if len(fill) != 1:
        raise ValueError("fill must be a single character")
    return fill * width


def generate_rectangle(width: int, height: int) -> str:
    problem = validate_dimensions(width, height)
    if problem is not None:
        raise ValueError(problem)
    row = build_row(width)
    return "\n".join([row] * height)


def render_labeled(width: int, height: int, label: Optional[str] = None) -> str:
    """Render the rectangle, prefixed by a title line when a label is supplied."""
    body = generate_rectangle(width, height)
    if label is None:
        return body
    return f"{label} ({width}x{height}):\n{body}"


def collect_dimensions(tokens: List[str]) -> Optional[List[int]]:
    """Parse exactly two dimension tokens; None signals that the input was unusable."""
    if len(tokens) != 2:
        return None
    parsed = []
    for token in tokens:
        value = parse_dimension(token)
        if value is None:
            return None
        parsed.append(value)
    return parsed


def main(argv: Optional[List[str]] = None) -> int:
    if argv is None:
        argv = sys.argv[1:]
    dimensions = collect_dimensions(argv)
    if dimensions is None:
        print("usage: rectangle.py WIDTH HEIGHT (positive integers)", file=sys.stderr)
        print(render_labeled(3, 2, "example"))
        return 1
    width, height = dimensions
    print(render_labeled(width, height))
    return 0


if __name__ == "__main__":
    sys.exit(main())

