def factorial_recursive(n, cache=None):
    """Return n! computed recursively, optionally reusing a memo dictionary."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("n must be an int")
    if n < 0:
        raise ValueError("n must be non-negative")
    if cache is None:
        cache = {0: 1, 1: 1}
    stored = cache.get(n)
    if stored is not None:
        return stored
    result = n * factorial_recursive(n - 1, cache)
    cache[n] = result
    return result


def parse_operand(text):
    """Convert user text into a non-negative int, or None when unusable."""
    cleaned = text.strip()
    if not cleaned:
        return None
    if cleaned.startswith("+"):
        cleaned = cleaned[1:]
    if not cleaned.isdigit():
        return None
    return int(cleaned)


def factorial_of_text(text, cache=None):
    """Parse text and return its factorial, or None if the text is not valid."""
    value = parse_operand(text)
    if value is None:
        return None
    return factorial_recursive(value, cache)


def format_row(text, value):
    label = "{:>6}!".format(text.strip())
    if value is None:
        return "{} = invalid input".format(label)
    digits = len(str(value))
    return "{} = {} ({} digit{})".format(label, value, digits, "" if digits == 1 else "s")


def build_report(inputs, cache=None):
    """Render one report line per input, sharing a memo cache across the batch."""
    if cache is None:
        cache = {0: 1, 1: 1}
    lines = []
    for text in inputs:
        lines.append(format_row(text, factorial_of_text(text, cache)))
    return "\n".join(lines)


def largest_valid(inputs):
    """Return the biggest parseable operand in the batch, or None if there is none."""
    best = None
    for text in inputs:
        value = parse_operand(text)
        if value is None:
            continue
        if best is None or value > best:
            best = value
    return best


def main():
    samples = ["5", "0", " 10 ", "3.5", "", "-4", "20"]
    cache = {0: 1, 1: 1}
    print(build_report(samples, cache))
    peak = largest_valid(samples)
    if peak is None:
        print("no valid operands were supplied")
    else:
        print("largest operand {} has factorial {}".format(peak, factorial_recursive(peak, cache)))
        print("memoised entries: {}".format(len(cache)))


if __name__ == "__main__":
    main()

