def contains_substring(main_string, sub_string):
    """Return True if sub_string occurs in main_string (case-sensitive)."""
    if main_string is None:
        raise ValueError("main_string must be a string, not None")
    if sub_string is None:
        raise ValueError("sub_string must be a string, not None")
    found = main_string.find(sub_string) != -1
    return found


def normalize_start(main_string, start):
    """Clamp a start offset into the valid range for main_string."""
    if start < 0:
        start += len(main_string)
        if start < 0:
            start = 0
    if start > len(main_string):
        start = len(main_string)
    return start


def first_position(main_string, sub_string, start=None):
    """Return the index of the first occurrence at/after start, else None."""
    if not contains_substring(main_string, sub_string):
        return None
    begin = 0 if start is None else normalize_start(main_string, start)
    index = main_string.find(sub_string, begin)
    if index == -1:
        return None
    return index


def all_positions(main_string, sub_string):
    """Return every start index at which sub_string occurs."""
    if sub_string == "":
        raise ValueError("sub_string must be a non-empty string")
    positions = []
    cursor = 0
    while True:
        index = first_position(main_string, sub_string, cursor)
        if index is None:
            break
        positions.append(index)
        cursor = index + 1
    return positions


def describe(main_string, sub_string):
    """Build a human-readable line about the search result."""
    index = first_position(main_string, sub_string)
    if index is None:
        return "%r does not contain %r" % (main_string, sub_string)
    hits = all_positions(main_string, sub_string)
    return "%r contains %r first at %d (%d hit(s))" % (
        main_string, sub_string, index, len(hits))


def main():
    cases = [
        ('Hello World', 'World'),
        ('Python', 'thon'),
        ('Hello World', 'world'),
        ('banana', 'an'),
    ]
    for main_string, sub_string in cases:
        print(describe(main_string, sub_string))
    print(contains_substring('Hello World', 'World'))
    print(contains_substring('Python', 'thon'))


if __name__ == "__main__":
    main()

