import random


def roll_die():
    """Return a random integer between 1 and 6 inclusive."""
    roll_result = random.randint(1, 6)
    return roll_result


def roll_many(count, seed=None):
    """Roll the die `count` times and return the list of results.

    When `seed` is given the sequence is reproducible; otherwise the
    module-level random state is used via `roll_die`.
    """
    if count < 1:
        raise ValueError("count must be at least 1")
    if seed is None:
        return [roll_die() for _ in range(count)]
    rng = random.Random(seed)
    return [rng.randint(1, 6) for _ in range(count)]


def tally(rolls):
    """Count how often each face appeared."""
    counts = {face: 0 for face in range(1, 7)}
    for roll in rolls:
        counts[roll] += 1
    return counts


def longest_run(rolls):
    """Return (face, length) for the longest streak of identical rolls.

    Returns None when `rolls` is empty.
    """
    best = None
    current_face = None
    current_length = 0
    for roll in rolls:
        if current_face is not None and roll == current_face:
            current_length += 1
        else:
            current_face = roll
            current_length = 1
        if best is None or current_length > best[1]:
            best = (current_face, current_length)
    return best


def format_report(rolls, label=None):
    """Build a human readable summary of a sequence of rolls."""
    lines = []
    if label is not None:
        lines.append("Report: {}".format(label))
    run = longest_run(rolls)
    if run is None:
        lines.append("No rolls recorded.")
        return "\n".join(lines)
    lines.append("Rolls: " + ", ".join(str(roll) for roll in rolls))
    counts = tally(rolls)
    for face in range(1, 7):
        lines.append("  {} | {:<3} {}".format(face, counts[face], "#" * counts[face]))
    lines.append("Average: {:.2f}".format(sum(rolls) / len(rolls)))
    lines.append("Longest run: {} x{}".format(run[0], run[1]))
    return "\n".join(lines)


def main():
    single = roll_die()
    print("Single roll:", single, "valid:", 1 <= single <= 6)
    print(format_report(roll_many(20), label="unseeded"))
