def split_email(email):
    """Split an email into (local, domain) or return None if there is no single '@'."""
    if not isinstance(email, str):
        return None
    parts = email.split('@')
    if len(parts) != 2:
        return None
    local, domain = parts
    if not local or not domain:
        return None
    return local, domain


def is_valid_email_basic(email):
    """Return True if the address has an '@' and at least one '.' after it."""
    parts = split_email(email)
    if parts is None:
        return False
    domain = parts[1]
    if '.' not in domain:
        return False
    for label in domain.split('.'):
        if not label:
            return False
    return True


def normalize_email(email):
    """Return the trimmed, lower-cased address, or None if it is not valid."""
    if email is None:
        return None
    candidate = email.strip() if isinstance(email, str) else email
    if not is_valid_email_basic(candidate):
        return None
    return candidate.lower()


def domain_of(email):
    """Return the lower-cased domain of a valid address, otherwise None."""
    normalized = normalize_email(email)
    if normalized is None:
        return None
    return split_email(normalized)[1]


def group_by_domain(emails):
    """Bucket valid addresses by domain; invalid ones land under the None key."""
    groups = {}
    for email in emails:
        groups.setdefault(domain_of(email), []).append(email)
    return groups


def format_report(groups):
    """Render one line per domain, plus a final line listing rejected inputs."""
    lines = []
    for domain in sorted(k for k in groups if k is not None):
        members = ', '.join(sorted(normalize_email(e) for e in groups[domain]))
        lines.append('{0} ({1}): {2}'.format(domain, len(groups[domain]), members))
    rejected = groups.get(None)
    if rejected is not None:
        lines.append('invalid ({0}): {1}'.format(len(rejected), ', '.join(repr(e) for e in rejected)))
    return '\n'.join(lines)


def main():
    samples = [
        'test@example.com',
        'invalid-email',
        '  Sales@Example.com ',
        'a@b@example.com',
        'user@localhost',
        'dev@sub.example.org',
        'trailing@example.',
        None,
    ]
    for sample in samples:
        print('{0!r:<26} -> {1}'.format(sample, is_valid_email_basic(sample)))
    print()
    print(format_report(group_by_domain(samples)))


if __name__ == '__main__':
    main()

