def simple_string_hash(s):
    """Return the sum of the code point values of the characters in s."""
    if not isinstance(s, str):
        raise TypeError("s must be a string")
    hash_value = 0
    for ch in s:
        hash_value += ord(ch)
    return hash_value


def hash_all(strings):
    """Hash every string in an iterable, returning a list of (string, hash)."""
    results = []
    for item in strings:
        if item is None:
            continue
        results.append((item, simple_string_hash(item)))
    return results


def find_collision(strings):
    """Return the first pair of distinct strings sharing a hash, else None."""
    seen = {}
    for text, value in hash_all(strings):
        previous = seen.get(value)
        if previous is None:
            seen[value] = text
        elif previous != text:
            return (previous, text)
    return None


def lookup(strings, target):
    """Return the string in strings whose hash equals target, else None."""
    for text, value in hash_all(strings):
        if value == target:
            return text
    return None


def format_report(strings, target=None):
    """Build a human readable report of the hashes of the given strings.

    If target is given, the report also states which string (if any) hashes
    to that value.
    """
    lines = ["string hashes"]
    for text, value in hash_all(strings):
        lines.append("%-10s -> %d" % (repr(text), value))
    collision = find_collision(strings)
    if collision is None:
        lines.append("no collisions found")
    else:
        lines.append("collision: %r and %r" % collision)
    if target is not None:
        match = lookup(strings, target)
        if match is None:
            lines.append("no string hashes to %d" % target)
        else:
            lines.append("%r hashes to %d" % (match, target))
    return "\n".join(lines)


def main():
    samples = ["abc", "A", "", "cba", "hash", None]
    print(format_report(samples, target=294))
    print()
    print(format_report(["one", "two"], target=1))


if __name__ == "__main__":
    main()

